async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(state.token)headers.Authorization=`Bearer ${state.token}`;let res=await fetch(`${API}${path}`,{...options,headers,credentials:'include'});let data=await res.json().catch(()=>({message:'Unexpected server response'}));if(!res.ok){const error=new Error(data.message||'Request failed');error.status=res.status;error.data=data;throw error;}return data;}
