async function dashboard(root){let d,branches=[];try{const qp=new URLSearchParams();if(state.selectedBranch)qp.set('branchId',state.selectedBranch);if(state.dashboardFrom)qp.set('from',state.dashboardFrom+'T00:00:00');if(state.dashboardTo)qp.set('to',state.dashboardTo+'T23:59:59');d=(await api('/dashboard'+(qp.toString()?'?'+qp.toString():''))).data;try{branches=(await api('/branches')).data}catch{branches=[]}}catch{d={patients:0,todayAppointments:0,openInvoices:0,todayCollections:0}}root.innerHTML=`${pageHeader('Good morning, '+esc(state.user?.name?.split(' ')[0]||'there'), 'Here is what is happening across your healthcare workspace today.', `<div class="flex gap-2 flex-wrap"><input type="date" id="dash-from" class="field max-w-[145px]" value="${state.dashboardFrom}"><input type="date" id="dash-to" class="field max-w-[145px]" value="${state.dashboardTo}"><select id="dash-branch" class="field max-w-[170px]"><option value="">All accessible branches</option>${branches.map(b=>`<option value="${b._id}" ${state.selectedBranch===b._id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><button class="btn-primary" data-action="new-patient"><i class="fa-solid fa-plus"></i> Register patient</button></div>`)}<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-6">${stat('Total active patients',d.patients,'fa-users','Patient records in this organization')}${stat("Today's appointments",d.todayAppointments,'fa-calendar-check','Selected date range')}${stat('Available doctors',d.availableDoctors||0,'fa-user-doctor','Doctors in selected branch scope')}${stat('Total staff',d.totalStaff||0,'fa-user-group','Active staff accounts')}${stat('Open invoices',d.openInvoices,'fa-file-invoice-dollar','Awaiting full payment')}${stat("Today's collections",'₹'+Number(d.todayCollections).toLocaleString('en-IN'),'fa-indian-rupee-sign','Payments recorded in selected range')}${stat('Active admissions',d.activeAdmissions||0,'fa-bed','Current inpatient stays')}${stat('Active branches',d.activeBranches||0,'fa-hospital','Branches in selected scope')}</div><div class="grid xl:grid-cols-3 gap-5"><section class="card xl:col-span-2 p-5"><div class="flex items-center justify-between mb-4"><div><h3 class="font-bold text-sm">Appointment activity</h3><p class="text-[11px] text-muted mt-1">Appointments scheduled over the coming week</p></div><button class="btn-secondary" data-route="Appointments">View calendar <i class="fa-solid fa-arrow-right"></i></button></div><div class="h-[260px]"><canvas id="activity-chart"></canvas></div></section><section class="card p-5"><h3 class="font-bold text-sm">Quick actions</h3><p class="text-[11px] text-muted mt-1 mb-4">Common front-desk workflows</p><div class="space-y-2">${[['Register a patient','fa-user-plus','Patients'],['Book an appointment','fa-calendar-plus','Appointments'],['Create an invoice','fa-file-circle-plus','Billing & Invoices'],['View doctors','fa-user-doctor','Doctors']].map(([t,i,r])=>`<button data-route="${r}" class="w-full flex items-center gap-3 p-3 rounded-lg border border-line hover:bg-canvas text-left"><span class="stat-icon"><i class="fa-solid ${i}"></i></span><span class="text-xs font-semibold flex-1">${t}</span><i class="fa-solid fa-chevron-right text-[10px] text-muted"></i></button>`).join('')}</div></section><section class="card xl:col-span-3 p-5"><h3 class="font-bold text-sm mb-3">Branch performance</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Branch</th><th>Patients</th><th>Appointments</th><th>Collections</th></tr></thead><tbody>${(d.branchPerformance||[]).map(b=>`<tr><td class="font-semibold">${esc(b.name)}</td><td>${b.patients}</td><td>${b.appointments}</td><td>₹${Number(b.collections||0).toLocaleString('en-IN')}</td></tr>`).join('')||'<tr><td colspan="4">No branch activity available.</td></tr>'}</tbody></table></div></section><section class="card xl:col-span-3 p-5"><div class="flex justify-between items-center mb-4"><div><h3 class="font-bold text-sm">Today's schedule</h3><p class="text-[11px] text-muted mt-1">Live appointments from your organization</p></div><button data-route="Appointments" class="text-xs text-mint font-semibold">Open schedule</button></div><div id="today-list" class="text-xs text-muted"><span class="cf-inline-load"><b><i></i><i></i><i></i></b>Loading appointments…</span></div></section></div>`;root.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.route)));root.querySelector('[data-action="new-patient"]').onclick=()=>patientModal();$('#dash-branch').onchange=e=>{state.selectedBranch=e.target.value;dashboard(root).catch(x=>toast(x.message,'error'))};$('#dash-from').onchange=e=>{state.dashboardFrom=e.target.value;dashboard(root).catch(x=>toast(x.message,'error'))};$('#dash-to').onchange=e=>{state.dashboardTo=e.target.value;dashboard(root).catch(x=>toast(x.message,'error'))};const ctx=$('#activity-chart');if(ctx){state.charts.push(new Chart(ctx,{type:'line',data:{labels:(d.appointmentTrend||[]).map(x=>new Date(x.date+'T00:00:00').toLocaleDateString('en-US',{weekday:'short'})),datasets:[{label:'Appointments',data:(d.appointmentTrend||[]).map(x=>x.count),borderColor:'#2d8b70',backgroundColor:'#2d8b7020',fill:true,tension:.38}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#eef2ef'}},x:{grid:{display:false}}}}}))}try{const ap=(await api('/appointments')).data;const today=new Date().toDateString();const list=ap.filter(a=>new Date(a.startAt).toDateString()===today);$('#today-list').innerHTML=list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Patient</th><th>Doctor</th><th>Status</th></tr></thead><tbody>${list.map(a=>`<tr><td>${new Date(a.startAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</td><td>${esc(a.patientId?.firstName)} ${esc(a.patientId?.lastName)} <span class="text-muted">· ${esc(a.patientId?.uhid)}</span></td><td>${esc(a.doctorId?.name)}</td><td><span class="pill">${esc(a.status.replace('_',' '))}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><i class="fa-regular fa-calendar"></i><p>No appointments scheduled for today.</p></div>'}catch{$('#today-list').textContent='Appointments could not be loaded.'}}
async function patients(root){const q=state.patientQuery||'',page=state.patientPage||1,branch=state.patientBranch||'',status=state.patientStatus||'active';const params=new URLSearchParams({q,page,limit:15,status});if(branch)params.set('branchId',branch);for(const [key,value] of Object.entries({sex:state.patientGender,ageMin:state.patientAgeMin,ageMax:state.patientAgeMax,from:state.patientFrom,to:state.patientTo,sort:state.patientSort}))if(value)params.set(key,value);const [result,branchResult]=await Promise.all([api('/patients?'+params),api('/branches').catch(()=>({data:[]}))]);root.innerHTML=`${pageHeader('Patients','A secure, searchable directory for patient registration and care records.',`${state.user?.role==='hospital_admin'||state.user?.permissions?.includes('settings.manage')?'<button id="patient-required-fields" class="btn-secondary">Required fields</button>':''}<button id="add-patient" class="btn-primary"><i class="fa-solid fa-plus"></i> Register patient</button>`)}<section class="card"><div class="p-4 grid sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-6 gap-3 border-b border-line"><input id="patient-search" value="${esc(q)}" class="field" placeholder="Name, phone, email or patient ID"><select id="patient-branch" class="field"><option value="">All accessible branches</option>${branchResult.data.map(b=>`<option value="${b._id}" ${branch===b._id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><select id="patient-status" class="field"><option value="active" ${status==='active'?'selected':''}>Active patients</option><option value="archived" ${status==='archived'?'selected':''}>Archived patients</option></select><select id="patient-gender" class="field"><option value="">All genders</option><option value="female" ${state.patientGender==='female'?'selected':''}>Female</option><option value="male" ${state.patientGender==='male'?'selected':''}>Male</option><option value="other" ${state.patientGender==='other'?'selected':''}>Other</option><option value="unknown" ${state.patientGender==='unknown'?'selected':''}>Not specified</option></select><input id="patient-age-min" class="field" type="number" min="0" max="120" placeholder="Min age" value="${esc(state.patientAgeMin||'')}"><input id="patient-age-max" class="field" type="number" min="0" max="120" placeholder="Max age" value="${esc(state.patientAgeMax||'')}"><input id="patient-from" class="field" type="date" title="Registered from" value="${esc(state.patientFrom||'')}"><input id="patient-to" class="field" class="field" type="date" title="Registered to" value="${esc(state.patientTo||'')}"><select id="patient-sort" class="field"><option value="recent" ${!state.patientSort||state.patientSort==='recent'?'selected':''}>Newest first</option><option value="registered" ${state.patientSort==='registered'?'selected':''}>Oldest first</option><option value="name" ${state.patientSort==='name'?'selected':''}>Name A–Z</option></select><div class="text-xs text-muted flex items-center">${result.pagination.total} patient records</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Patient</th><th>Patient ID</th><th>Contact</th><th>Age / Sex</th><th>Branch</th><th>Registered</th><th>Actions</th></tr></thead><tbody>${result.data.map(p=>`<tr><td><div class="font-semibold text-ink">${esc(p.firstName)} ${esc(p.lastName)}</div><div class="text-[10px] text-muted mt-1">${p.active?'Active':'Archived'}</div></td><td><span class="font-semibold">${esc(p.uhid)}</span></td><td>${esc(p.phone||'—')}<div class="text-[10px] text-muted">${esc(p.email||'')}</div></td><td>${p.dob?Math.floor((Date.now()-new Date(p.dob))/(365.25*86400000))+' yrs':'—'} / ${esc(p.sex||'—')}</td><td>${esc(p.branchId?.name||'—')}</td><td>${new Date(p.createdAt).toLocaleDateString()}</td><td><div class="flex gap-1"><button class="icon-btn" data-view="${p._id}" title="Open profile"><i class="fa-regular fa-eye"></i></button>${p.active?`<button class="icon-btn" data-invite="${p._id}" title="Invite to patient portal"><i class="fa-regular fa-paper-plane"></i></button>`:`<button class="icon-btn" data-restore="${p._id}" title="Restore"><i class="fa-solid fa-rotate-left"></i></button>`}</div></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty-state"><i class="fa-solid fa-users"></i><p>No patient records found.</p></div></td></tr>'}</tbody></table></div><div class="p-4 border-t border-line flex items-center justify-between text-xs text-muted"><span>Page ${result.pagination.page} of ${Math.max(1,result.pagination.pages)} · ${result.pagination.total} records</span><div class="flex gap-2"><button id="patient-prev" class="btn-secondary" ${page<=1?'disabled':''}>Previous</button><button id="patient-next" class="btn-secondary" ${page>=result.pagination.pages?'disabled':''}>Next</button></div></div></section>`;$('#add-patient').onclick=()=>patientModal();if($('#patient-required-fields'))$('#patient-required-fields').onclick=()=>patientRequiredFields();$('#patient-gender').onchange=e=>{state.patientGender=e.target.value;state.patientPage=1;patients(root)};$('#patient-age-min').onchange=e=>{state.patientAgeMin=e.target.value;state.patientPage=1;patients(root)};$('#patient-age-max').onchange=e=>{state.patientAgeMax=e.target.value;state.patientPage=1;patients(root)};$('#patient-from').onchange=e=>{state.patientFrom=e.target.value;state.patientPage=1;patients(root)};$('#patient-to').onchange=e=>{state.patientTo=e.target.value;state.patientPage=1;patients(root)};$('#patient-sort').onchange=e=>{state.patientSort=e.target.value;state.patientPage=1;patients(root)};$('#patient-search').onkeydown=e=>{if(e.key==='Enter'){state.patientQuery=e.target.value;state.patientPage=1;patients(root)}};$('#patient-branch').onchange=e=>{state.patientBranch=e.target.value;state.patientPage=1;patients(root)};$('#patient-status').onchange=e=>{state.patientStatus=e.target.value;state.patientPage=1;patients(root)};$('#patient-prev').onclick=()=>{state.patientPage=Math.max(1,page-1);patients(root)};$('#patient-next').onclick=()=>{state.patientPage=page+1;patients(root)};root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>patientDetail(b.dataset.view));root.querySelectorAll('[data-invite]').forEach(b=>b.onclick=()=>patientInvite(b.dataset.invite));root.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{try{await api(`/patients/${b.dataset.restore}/restore`,{method:'POST'});toast('Patient restored');patients(root)}catch(e){toast(e.message,'error')}})}
async function patientRequiredFields(){try{const current=(await api('/patients/settings/registration')).data.requiredFields;const options=[['lastName','Last name'],['dob','Date of birth'],['sex','Gender'],['maritalStatus','Marital status'],['phone','Mobile number'],['alternatePhone','Alternate mobile'],['email','Email address'],['bloodGroup','Blood group'],['occupation','Occupation'],['address','Address'],['city','City'],['state','State'],['country','Country'],['postalCode','PIN code'],['emergencyContact.name','Emergency contact name'],['emergencyContact.phone','Emergency contact number']];showModal('Required patient registration fields',`<form id="required-fields-form" class="grid sm:grid-cols-2 gap-3"><label class="text-xs font-semibold"><input type="checkbox" checked disabled> First name (always required)</label>${options.map(([k,l])=>`<label class="text-xs"><input type="checkbox" name="field" value="${k}" ${current.includes(k)?'checked':''}> ${l}</label>`).join('')}</form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="required-fields-form">Save requirements</button>');$('#required-fields-form').onsubmit=async e=>{e.preventDefault();try{await api('/patients/settings/registration',{method:'PATCH',body:JSON.stringify({requiredFields:new FormData(e.target).getAll('field')})});closeModal();toast('Patient registration requirements saved')}catch(x){toast(x.message,'error')}}}catch(e){toast(e.message,'error')}}
async function patientModal(){const branches=(await api('/branches')).data;showModal('Register new patient',`<form id="patient-form" class="field-grid"><div><label class="field-label">First name *</label><input class="field" name="firstName" required maxlength="80"></div><div><label class="field-label">Last name</label><input class="field" name="lastName" maxlength="80"></div><div><label class="field-label">Branch *</label><select class="field" name="branchId" required>${branches.map(b=>`<option value="${b._id}" ${state.selectedBranch===b._id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div><label class="field-label">Date of birth</label><input class="field" name="dob" type="date" max="${new Date().toISOString().slice(0,10)}"></div><div><label class="field-label">Gender</label><select class="field" name="sex"><option value="unknown">Not specified</option><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></select></div><div><label class="field-label">Marital status</label><select class="field" name="maritalStatus"><option value="">Not specified</option><option value="single">Single</option><option value="married">Married</option><option value="divorced">Divorced</option><option value="widowed">Widowed</option><option value="other">Other</option></select></div><div><label class="field-label">Mobile number</label><input class="field" name="phone" type="tel" maxlength="20"></div><div><label class="field-label">Alternate mobile</label><input class="field" name="alternatePhone" type="tel" maxlength="20"></div><div><label class="field-label">Email address</label><input class="field" name="email" type="email"></div><div><label class="field-label">Blood group</label><select class="field" name="bloodGroup"><option value="">Select</option>${['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(x=>`<option>${x}</option>`).join('')}</select></div><div><label class="field-label">Occupation</label><input class="field" name="occupation"></div><div><label class="field-label">PIN code</label><input class="field" name="postalCode" maxlength="12"></div><div class="full"><label class="field-label">Address</label><input class="field" name="address"></div><div><label class="field-label">City</label><input class="field" name="city"></div><div><label class="field-label">State</label><input class="field" name="state"></div><div><label class="field-label">Country</label><input class="field" name="country" value="India"></div><div><label class="field-label">Emergency contact name</label><input class="field" name="emergencyContact[name]"></div><div><label class="field-label">Emergency contact number</label><input class="field" name="emergencyContact[phone]"></div><div><label class="field-label">Relationship</label><input class="field" name="emergencyContact[relationship]"></div><div><label class="field-label">Known allergies</label><input class="field" name="allergies" placeholder="Comma separated"></div><div><label class="field-label">Existing conditions</label><input class="field" name="conditions" placeholder="Comma separated"></div><div><label class="field-label">Current medications</label><input class="field" name="currentMedications" placeholder="Comma separated"></div><div><label class="field-label">Previous surgeries</label><input class="field" name="previousSurgeries" placeholder="Comma separated"></div><div class="full"><label class="field-label">Family medical history</label><textarea class="field h-20 py-3" name="familyHistory"></textarea></div><div class="full"><label class="field-label">Additional notes</label><textarea class="field h-20 py-3" name="notes"></textarea></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="patient-form">Save patient</button>');$('#patient-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),d={};for(const [k,v] of f.entries()){const m=k.match(/^emergencyContact\[(.+)\]$/);if(m){d.emergencyContact=d.emergencyContact||{};d.emergencyContact[m[1]]=v;continue}d[k]=v}for(const k of ['allergies','conditions','currentMedications','previousSurgeries'])d[k]=d[k]?d[k].split(',').map(x=>x.trim()).filter(Boolean):[];if(!d.dob)delete d.dob;try{await api('/patients',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Patient registered successfully');state.patientQuery='';state.patientPage=1;navigate('Patients')}catch(x){if(x.message.includes('same phone or email')){if(confirm('A possible duplicate was found. Register this patient anyway?')){d.confirmPossibleDuplicate=true;try{await api('/patients',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Patient registered with duplicate confirmation');navigate('Patients')}catch(err){toast(err.message,'error')}}}else toast(x.message,'error')}}}
async function patientInvite(id){try{const p=(await api('/patients/'+id)).data;const email=p.email||'';showModal('Invite patient to portal',`<form id="patient-invite-form"><label class="field-label">Patient email</label><input class="field" name="email" type="email" value="${esc(email)}" required><p class="text-xs text-muted mt-2">The patient receives a secure invitation link. SMTP must be configured on the server.</p></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="patient-invite-form">Send invitation</button>');$('#patient-invite-form').onsubmit=async e=>{e.preventDefault();try{const email=new FormData(e.target).get('email');const r=await api(`/patients/${id}/invite-portal`,{method:'POST',body:JSON.stringify({email})});closeModal();toast(r.message)}catch(x){toast(x.message,'error')}}}catch(e){toast(e.message,'error')}}
async function patientDetail(id,tab='Overview'){const root=$('#page-content');const p=(await api('/patients/'+id)).data;const summary=(await api(`/patients/${id}/summary`)).data;const canClinical=state.user?.role==='hospital_admin'||state.user?.permissions?.includes('*')||state.user?.permissions?.includes('clinical.notes');const canEdit=state.user?.role==='hospital_admin'||state.user?.permissions?.includes('*')||state.user?.permissions?.includes('patients.edit');const canBilling=state.user?.role==='hospital_admin'||state.user?.permissions?.includes('*')||state.user?.permissions?.includes('billing.view');const clinicalTabs=['Medical History','Visits','Consultations','Prescriptions','Lab Reports','Documents','Notes'];const tabs=['Overview','Personal Information','Medical History','Visits','Appointments','Consultations','Prescriptions','Lab Reports','Documents','Billing & Payments','Notes','Profile Requests','Activity History'].filter(t=>(canClinical||!clinicalTabs.includes(t))&&(canBilling||t!=='Billing & Payments')&&(canEdit||t!=='Profile Requests'));let content='';if(tab==='Overview')content=`<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-3 mb-5">${[stat('Total visits',summary.visits,'fa-stethoscope','Recorded consultations'),stat('Appointments',summary.appointments,'fa-calendar-check','All appointment records'),stat('Prescriptions',summary.prescriptions,'fa-prescription','Finalized prescriptions'),...(summary.outstandingBalance!==undefined?[stat('Outstanding balance','₹'+Number(summary.outstandingBalance).toLocaleString('en-IN'),'fa-file-invoice-dollar','Unpaid and partial invoices')]:[])].join('')}</div><div class="grid lg:grid-cols-2 gap-4"><section class="card p-5"><h3 class="font-bold text-sm mb-4">Patient overview</h3><div class="grid grid-cols-2 gap-4 text-xs">${[['Patient ID',p.uhid],['Date of birth',p.dob?new Date(p.dob).toLocaleDateString():'—'],['Gender',p.sex],['Blood group',p.bloodGroup||'—'],['Phone',p.phone||'—'],['Email',p.email||'—'],['Branch',p.branchId?.name||'—'],['Registered',new Date(p.createdAt).toLocaleDateString()]].map(([k,v])=>`<div><div class="text-muted mb-1">${k}</div><b>${esc(v)}</b></div>`).join('')}</div></section>${canClinical?`<section class="card p-5"><h3 class="font-bold text-sm mb-3">Clinical summary</h3><div class="text-xs space-y-3"><div><span class="text-muted">Allergies</span><p class="font-semibold mt-1">${esc((p.allergies||[]).join(', ')||'None recorded')}</p></div><div><span class="text-muted">Conditions</span><p class="font-semibold mt-1">${esc((p.conditions||[]).join(', ')||'None recorded')}</p></div><div><span class="text-muted">Current medications</span><p class="font-semibold mt-1">${esc((p.currentMedications||[]).join(', ')||'None recorded')}</p></div></div></section>`:''}</div>`;else if(tab==='Personal Information')content=`<section class="card p-5"><h3 class="font-bold text-sm mb-4">Personal and contact information</h3><div class="grid sm:grid-cols-2 gap-4 text-xs">${[['Full name',p.firstName+' '+p.lastName],['Marital status',p.maritalStatus||'—'],['Occupation',p.occupation||'—'],['Mobile',p.phone||'—'],['Alternate mobile',p.alternatePhone||'—'],['Email',p.email||'—'],['Address',p.address||'—'],['City',p.city||'—'],['State',p.state||'—'],['Country',p.country||'—'],['PIN code',p.postalCode||'—'],['Emergency contact',p.emergencyContact?.name||'—']].map(([k,v])=>`<div><div class="text-muted mb-1">${k}</div><b>${esc(v)}</b></div>`).join('')}</div>${canEdit?`<div class="flex gap-2 mt-5 flex-wrap"><button class="btn-primary" id="edit-patient">Edit patient details</button><button class="btn-secondary" id="upload-photo">Upload profile photo</button></div>`:''}</section>`;else if(tab==='Medical History'){const r=(await api(`/patients/${id}/medical-history`)).data;content=`<section class="card p-5"><div class="flex justify-between items-center mb-4"><h3 class="font-bold text-sm">Medical history timeline</h3>${canClinical?'<button class="btn-primary" id="add-history">Add entry</button>':''}</div>${r.map(x=>`<div class="border-b border-line py-3"><div class="flex justify-between text-xs"><b>${esc(x.title)}</b><span class="text-muted">${new Date(x.recordedAt).toLocaleDateString()}</span></div><p class="text-xs text-muted mt-1">${esc(x.category.replaceAll('_',' '))} · ${esc(x.createdBy?.name||'Care team')}</p><p class="text-sm mt-2">${esc(x.details||'')}</p></div>`).join('')||'<div class="empty-state">No medical history entries recorded.</div>'}</section>`}else if(tab==='Documents'){const docs=(await api(`/patients/${id}/documents`)).data;content=`<section class="card p-5"><div class="flex justify-between items-center mb-4"><h3 class="font-bold text-sm">Patient documents</h3>${canClinical?'<button class="btn-primary" id="upload-document">Upload document</button>':''}</div>${docs.map(d=>`<div class="flex items-center justify-between gap-3 py-3 border-b border-line text-xs"><div><b>${esc(d.originalName)}</b><p class="text-muted mt-1">${esc(d.category)} · ${(d.size/1024).toFixed(1)} KB · ${new Date(d.createdAt).toLocaleDateString()}</p></div><button class="btn-secondary" data-download="${d._id}">Download</button></div>`).join('')||'<div class="empty-state">No documents uploaded.</div>'}</section>`}else if(tab==='Profile Requests'){const requests=(await api(`/patients/${id}/profile-change-requests`)).data;content=`<section class="card p-5"><h3 class="font-bold text-sm mb-3">Patient profile change requests</h3>${requests.map(r=>`<div class="border-b border-line py-3"><div class="flex justify-between text-xs"><b>${esc(r.status)}</b><span class="text-muted">${new Date(r.createdAt).toLocaleString()}</span></div><pre class="text-xs whitespace-pre-wrap mt-2">${esc(JSON.stringify(r.changes,null,2))}</pre>${r.status==='pending'?`<div class="flex gap-2 mt-3"><button class="btn-primary" data-review="${r._id}" data-status="approved">Approve</button><button class="btn-secondary" data-review="${r._id}" data-status="rejected">Reject</button></div>`:''}</div>`).join('')||'<div class="empty-state">No profile change requests.</div>'}</section>`}else if(tab==='Notes'){const notes=(await api(`/patients/${id}/notes`)).data;content=`<section class="card p-5"><div class="flex justify-between items-center mb-4"><h3 class="font-bold text-sm">Clinical notes</h3>${canClinical?'<button class="btn-primary" id="add-note">Add note</button>':''}</div>${notes.map(n=>`<div class="border-b border-line py-3"><p class="text-sm">${esc(n.body)}</p><p class="text-[10px] text-muted mt-2">${esc(n.createdBy?.name||'Care team')} · ${new Date(n.createdAt).toLocaleString()}</p></div>`).join('')||'<div class="empty-state">No notes available.</div>'}</section>`}else{const map={'Visits':'/consultations','Appointments':'/appointments','Consultations':'/consultations','Prescriptions':'/prescriptions','Lab Reports':'/lab-orders','Billing & Payments':'/invoices'};if(map[tab]){const d=(await api(map[tab])).data||[];const filtered=d.filter(x=>String(x.patientId?._id||x.patientId)===id);content=`<section class="card p-5"><h3 class="font-bold text-sm mb-4">${tab}</h3><div class="table-wrap"><table class="data-table"><tbody>${filtered.map(x=>`<tr><td>${esc(x.invoiceNo||x.status||x._id)}</td><td>${new Date(x.createdAt||x.startAt).toLocaleString()}</td><td>${esc(x.status||'—')}</td></tr>`).join('')||'<tr><td>No records available in this module.</td></tr>'}</tbody></table></div></section>`}else if(tab==='Activity History'){const activity=(await api(`/patients/${id}/activity`)).data;content=`<section class="card p-5"><h3 class="font-bold text-sm mb-3">Patient activity</h3>${activity.map(a=>`<div class="py-3 border-b border-line text-xs"><b>${esc(a.action)}</b><p class="text-muted mt-1">${esc(a.userId?.name||'System')} · ${new Date(a.createdAt).toLocaleString()}</p></div>`).join('')||'<div class="empty-state">No patient activity recorded.</div>'}</section>`}else content=`<section class="card p-5"><p class="text-sm text-muted">No data is available for this tab.</p></section>`}root.innerHTML=`${pageHeader(`${esc(p.firstName)} ${esc(p.lastName)}`,`Patient ID ${esc(p.uhid)} · ${esc(p.branchId?.name||'Branch')}`,`<button class="btn-secondary" id="back-patients"><i class="fa-solid fa-arrow-left"></i> Patients</button>`)}<div class="flex flex-wrap gap-2 mb-5">${tabs.map(t=>`<button class="btn-secondary ${tab===t?'!bg-forest !text-white':''}" data-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div>${content}`;$('#back-patients').onclick=()=>navigate('Patients');root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>patientDetail(id,b.dataset.tab));if($('#edit-patient'))$('#edit-patient').onclick=()=>patientEditModal(p);if($('#upload-photo'))$('#upload-photo').onclick=()=>{showModal('Upload profile photo',`<form id="photo-form"><input class="field" type="file" name="file" accept=".jpg,.jpeg,.png" required><p class="text-xs text-muted mt-2">JPEG or PNG · maximum 10 MB</p></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="photo-form">Upload photo</button>');$('#photo-form').onsubmit=async e=>{e.preventDefault();const res=await fetch(`${API}/patients/${id}/photo`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`},credentials:'include',body:new FormData(e.target)});const d=await res.json();if(!res.ok)return toast(d.message||'Photo upload failed','error');closeModal();toast('Patient photo updated');patientDetail(id,'Personal Information')}};root.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{try{await api(`/patients/${id}/profile-change-requests/${b.dataset.review}/review`,{method:'POST',body:JSON.stringify({status:b.dataset.status})});toast('Profile change request reviewed');patientDetail(id,'Profile Requests')}catch(e){toast(e.message,'error')}});if($('#add-history'))$('#add-history').onclick=()=>{showModal('Add medical history',`<form id="history-form" class="space-y-3"><select class="field" name="category"><option value="illness">Past illness</option><option value="chronic_condition">Chronic condition</option><option value="allergy">Allergy</option><option value="surgery">Previous surgery</option><option value="family_history">Family history</option><option value="medication">Medication</option><option value="note">Clinical note</option></select><input class="field" name="title" placeholder="Title" required><textarea class="field h-24 py-3" name="details" placeholder="Details"></textarea></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="history-form">Save entry</button>');$('#history-form').onsubmit=async e=>{e.preventDefault();try{await api(`/patients/${id}/medical-history`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Medical history saved');patientDetail(id,'Medical History')}catch(x){toast(x.message,'error')}}};if($('#add-note'))$('#add-note').onclick=()=>{showModal('Add clinical note',`<form id="note-form"><textarea class="field h-32 py-3" name="body" required maxlength="10000" placeholder="Enter a clinical note"></textarea></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="note-form">Save note</button>');$('#note-form').onsubmit=async e=>{e.preventDefault();try{await api(`/patients/${id}/notes`,{method:'POST',body:JSON.stringify({body:new FormData(e.target).get('body')})});closeModal();toast('Note saved');patientDetail(id,'Notes')}catch(x){toast(x.message,'error')}}};if($('#upload-document'))$('#upload-document').onclick=()=>{showModal('Upload patient document',`<form id="doc-form" class="space-y-3"><select class="field" name="category"><option value="other">Other</option><option value="prescription">Prescription</option><option value="lab_report">Lab report</option><option value="radiology_report">Radiology report</option><option value="discharge_summary">Discharge summary</option><option value="medical_certificate">Medical certificate</option><option value="insurance">Insurance</option></select><input class="field" name="file" type="file" accept=".pdf,.png,.jpg,.jpeg" required><p class="text-xs text-muted">PDF, JPEG or PNG · maximum 10 MB</p></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="doc-form">Upload</button>');$('#doc-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target);const res=await fetch(`${API}/patients/${id}/documents`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`},credentials:'include',body:form});const data=await res.json();if(!res.ok)return toast(data.message||'Upload failed','error');closeModal();toast('Document uploaded');patientDetail(id,'Documents') }};root.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{try{const res=await fetch(`${API}/patients/${id}/documents/${b.dataset.download}/download`,{headers:{Authorization:`Bearer ${state.token}`},credentials:'include'});if(!res.ok)throw new Error('Document download failed');const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='patient-document';a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message,'error')}})}
async function patientEditModal(p){const fields=[['firstName','First name'],['lastName','Last name'],['phone','Mobile'],['alternatePhone','Alternate mobile'],['email','Email'],['address','Address'],['city','City'],['state','State'],['postalCode','PIN code'],['occupation','Occupation']];showModal('Edit patient details',`<form id="patient-edit-form" class="field-grid">${fields.map(([k,l])=>`<div><label class="field-label">${l}</label><input class="field" name="${k}" value="${esc(p[k]||'')}"></div>`).join('')}</form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="patient-edit-form">Save changes</button>');$('#patient-edit-form').onsubmit=async e=>{e.preventDefault();try{await api('/patients/'+p._id,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Patient details updated');patientDetail(p._id,'Personal Information')}catch(x){toast(x.message,'error')}}}
async function patientEmrPage(root){const d=(await api('/patient-portal/emr')).data;root.innerHTML=`${pageHeader('My medical record','Your released medical information, prescriptions and follow-up guidance.')}<section class="card p-5 mb-4"><h2 class="font-bold text-lg">${esc(d.patient.firstName)} ${esc(d.patient.lastName)}</h2><p class="text-xs text-muted mt-1">${esc(d.patient.uhid)} · ${esc(d.patient.bloodGroup||'Blood group not recorded')}</p><p class="text-xs text-muted mt-3">Only records released by your clinic are shown here. Draft consultations and private doctor notes are not available in the patient portal.</p></section><div class="grid xl:grid-cols-2 gap-4">${[['Diagnoses',d.diagnoses.map(x=>`${x.description} · ${x.certainty} · ${x.status}`)],['Treatment instructions',d.treatmentPlans.map(x=>x.instructions||x.notes||'Treatment plan')],['Clinical summaries',d.clinicalSummaries.map(x=>`${new Date(x.createdAt).toLocaleDateString()} · ${x.assessment||x.clinicalImpression||x.chiefComplaint||'Released summary'} · ${x.followUpRecommendations||''}`)],['Medical history released by clinic',d.medicalHistory.map(x=>`${x.category}: ${x.title} · ${x.details||''}`)],['Verified lab reports',d.laboratoryResults.map(x=>`${new Date(x.verifiedAt||x.createdAt).toLocaleDateString()} · ${(x.tests||[]).map(t=>t.name).join(', ')}`)],['Released documents',d.documents.map(x=>`${x.category} · ${x.originalName}`)]].map(([title,items])=>`<section class="card p-4"><h3 class="font-bold mb-3">${title}</h3>${items.length?items.map(x=>`<div class="border-t border-line py-2 text-xs">${esc(x)}</div>`).join(''):'<p class="text-xs text-muted">No released records.</p>'}</section>`).join('')}</div><section class="card p-4 mt-4"><h3 class="font-bold mb-3">My prescriptions</h3>${d.prescriptions.length?d.prescriptions.map(x=>`<div class="border-t border-line py-3 flex flex-wrap justify-between gap-2 text-xs"><div><b>${esc(x.prescriptionNo||'Prescription')}</b> · ${new Date(x.finalizedAt||x.createdAt).toLocaleDateString()}<p class="text-muted mt-1">${(x.items||[]).map(i=>esc(i.medicine)).join(', ')}</p></div><button class="btn-secondary" data-patient-rx-pdf="${x._id}">Download PDF</button></div>`).join(''):'<p class="text-xs text-muted">No released prescriptions.</p>'}</section>`;root.querySelectorAll('[data-patient-rx-pdf]').forEach(b=>b.onclick=async()=>{try{const r=await fetch(`${API}/patient-portal/prescriptions/${b.dataset.patientRxPdf}/pdf`,{headers:{Authorization:`Bearer ${state.token}`},credentials:'include'});if(!r.ok)throw new Error('Prescription PDF unavailable');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='careflow-prescription.pdf';a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message,'error')}})}
async function patientPortalDashboard(root){const d=(await api('/patient-portal/dashboard')).data;root.innerHTML=`${pageHeader('Welcome, '+esc(d.patient.firstName),'Your personal care space. View appointments, prescriptions, reports and billing securely.')}<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-5">${stat('Upcoming appointments',d.counts.upcomingAppointments,'fa-calendar-check','Scheduled visits')}${stat('Prescriptions',d.counts.prescriptions,'fa-prescription','Finalized prescriptions')}${stat('Lab reports',d.counts.verifiedReports,'fa-flask','Verified reports available')}${stat('Outstanding invoices',d.counts.outstandingInvoices,'fa-file-invoice-dollar','Invoices requiring attention')}</div><div class="grid lg:grid-cols-2 gap-5"><section class="card p-5"><h3 class="font-bold text-sm mb-3">Upcoming appointments</h3>${d.upcomingAppointments.map(a=>`<div class="py-3 border-b border-line text-xs"><b>${esc(a.doctorId?.name||'Doctor')}</b><p class="text-muted mt-1">${new Date(a.startAt).toLocaleString()} · ${esc(a.branchId?.name||'')}</p><span class="text-mint">${esc(a.status)}</span></div>`).join('')||'<div class="empty-state">No upcoming appointments.</div>'}</section><section class="card p-5"><h3 class="font-bold text-sm mb-3">Recent prescriptions</h3>${d.recentPrescriptions.map(x=>`<div class="py-3 border-b border-line text-xs"><b>${esc(x.doctorId?.name||'Prescribing doctor')}</b><p class="text-muted mt-1">${new Date(x.createdAt).toLocaleDateString()} · ${(x.items||[]).length} medicines</p></div>`).join('')||'<div class="empty-state">No prescriptions available.</div>'}</section><section class="card p-5"><h3 class="font-bold text-sm mb-3">Latest verified lab reports</h3>${d.latestLabReports.map(x=>`<div class="py-3 border-b border-line text-xs"><b>${esc((x.tests||[]).map(t=>t.name).join(', ')||'Lab report')}</b><p class="text-muted mt-1">Verified ${x.verifiedAt?new Date(x.verifiedAt).toLocaleDateString():'—'}</p></div>`).join('')||'<div class="empty-state">No verified reports available.</div>'}</section><section class="card p-5"><h3 class="font-bold text-sm mb-3">Outstanding bills</h3>${d.outstandingInvoices.map(x=>`<div class="py-3 border-b border-line text-xs flex justify-between"><div><b>${esc(x.invoiceNo)}</b><p class="text-muted mt-1">${esc(x.status)}</p></div><b>₹${Number(x.total-x.paid).toLocaleString('en-IN')}</b></div>`).join('')||'<div class="empty-state">No outstanding invoices.</div>'}</section></div>`}
async function patientPortalAppointments(root){const d=(await api('/patient-portal/appointments')).data;root.innerHTML=`${pageHeader('My appointments','Your visit schedule and appointment history.','<button id="patient-find-doctor" class="btn-primary">Find a doctor</button>')}<section class="card p-5"><div class="table-wrap"><table class="data-table"><thead><tr><th>Doctor</th><th>Department</th><th>Date & time</th><th>Branch</th><th>Status</th><th></th></tr></thead><tbody>${d.map(a=>`<tr><td>${esc(a.doctorId?.name||'—')}</td><td>${esc(a.doctorId?.specialty||'—')}</td><td>${new Date(a.startAt).toLocaleString()}</td><td>${esc(a.branchId?.name||'—')}</td><td>${esc(a.status)}</td><td>${['scheduled','booked','confirmed'].includes(a.status)?`<div class="flex gap-1"><button class="btn-secondary" data-reschedule-request="${a._id}">Request reschedule</button><button class="btn-secondary" data-cancel="${a._id}">Cancel</button></div>`:''}</td></tr>`).join('')||'<tr><td colspan="6">No appointment history.</td></tr>'}</tbody></table></div></section>`;$('#patient-find-doctor').onclick=()=>navigate('Find a Doctor');root.querySelectorAll('[data-reschedule-request]').forEach(b=>b.onclick=()=>patientRescheduleRequest(d.find(a=>a._id===b.dataset.rescheduleRequest)));root.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancel this appointment?'))return;try{await api(`/patient-portal/appointments/${b.dataset.cancel}/cancel`,{method:'POST',body:'{}'});toast('Appointment cancelled');patientPortalAppointments(root)}catch(e){toast(e.message,'error')}})}
async function patientPortalList(root,type){const map={prescriptions:['/patient-portal/prescriptions','Prescriptions'], 'lab-reports':['/patient-portal/lab-reports','Verified laboratory reports'],invoices:['/patient-portal/invoices','Billing & payments']};const [url,title]=map[type],d=(await api(url)).data;root.innerHTML=`${pageHeader(title,'Records released by your healthcare provider.')}<section class="card p-5"><div class="table-wrap"><table class="data-table"><thead><tr>${type==='prescriptions'?'<th>Date</th><th>Doctor</th><th>Medicines</th><th>Status</th>':type==='lab-reports'?'<th>Test</th><th>Ordered</th><th>Verified</th><th>Results</th>':'<th>Invoice</th><th>Date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th>Payments</th>'}</tr></thead><tbody>${d.map(x=>type==='prescriptions'?`<tr><td>${new Date(x.createdAt).toLocaleDateString()}</td><td>${esc(x.doctorId?.name||'—')}</td><td>${(x.items||[]).map(i=>`<div class="mb-2"><b>${esc(i.medicine||'Medicine')}</b><div class="text-[10px] text-muted">${esc([i.strength,i.dosage,i.frequency,i.duration,i.route,i.instructions].filter(Boolean).join(' · ')||'No additional instructions recorded')}</div></div>`).join('')}</td><td>${esc(x.status)}</td></tr>`:type==='lab-reports'?`<tr><td>${(x.tests||[]).map(t=>esc(t.name)).join(', ')}</td><td>${new Date(x.createdAt).toLocaleDateString()}</td><td>${x.verifiedAt?new Date(x.verifiedAt).toLocaleDateString():'—'}</td><td><details><summary class="cursor-pointer text-mint">View results</summary><pre class="text-[10px] whitespace-pre-wrap mt-2">${esc(JSON.stringify(x.results||{},null,2))}</pre></details></td></tr>`:`<tr><td>${esc(x.invoiceNo)}</td><td>${new Date(x.createdAt).toLocaleDateString()}</td><td>₹${Number(x.total).toLocaleString('en-IN')}</td><td>₹${Number(x.paid).toLocaleString('en-IN')}</td><td>₹${Number(x.total-x.paid).toLocaleString('en-IN')}</td><td>${esc(x.status)}</td><td><div class="flex gap-1"><button class="btn-secondary" data-payments="${x._id}">History</button><button class="btn-secondary" data-print="${x._id}">Print</button></div></td></tr>`).join('')||'<tr><td colspan="7">No records have been released.</td></tr>'}</tbody></table></div></section>`;root.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>printPatientInvoice(d.find(x=>x._id===b.dataset.print)));root.querySelectorAll('[data-payments]').forEach(b=>b.onclick=async()=>{try{const r=(await api(`/patient-portal/invoices/${b.dataset.payments}/payments`)).data;showModal('Payment history',r.map(x=>`<div class="py-3 border-b border-line text-xs"><b>₹${Number(x.amount).toLocaleString('en-IN')}</b><p class="text-muted mt-1">${esc(x.method)} · ${new Date(x.createdAt).toLocaleString()}</p></div>`).join('')||'No payments recorded.','<button class="btn-secondary" data-close>Close</button>')}catch(e){toast(e.message,'error')}})}
function printPatientInvoice(invoice){if(!invoice)return;const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print this invoice.','error');return}const lines=(invoice.items||[]).map(i=>`<tr><td>${esc(i.description)}</td><td>${Number(i.quantity)}</td><td>₹${Number(i.unitPrice).toFixed(2)}</td><td>₹${Number(i.amount).toFixed(2)}</td></tr>`).join('');w.document.write(`<!doctype html><html><head><title>Invoice ${esc(invoice.invoiceNo)}</title><style>body{font:14px Arial,sans-serif;color:#172b25;padding:36px}h1{color:#173f35}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{text-align:left;padding:10px;border-bottom:1px solid #ddd}.total{text-align:right;margin-top:24px;line-height:2}</style></head><body><h1>CareFlow</h1><h2>Invoice ${esc(invoice.invoiceNo)}</h2><p>Date: ${new Date(invoice.createdAt).toLocaleDateString()}</p><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>${lines}</tbody></table><div class="total"><div>Subtotal: ₹${Number(invoice.subtotal).toFixed(2)}</div><div>Discount: ₹${Number(invoice.discount).toFixed(2)}</div><div>Tax: ₹${Number(invoice.tax).toFixed(2)}</div><h3>Total: ₹${Number(invoice.total).toFixed(2)}</h3><div>Paid: ₹${Number(invoice.paid).toFixed(2)}</div><div>Balance: ₹${Number(invoice.total-invoice.paid).toFixed(2)}</div></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
async function patientPortalDocuments(root){const d=(await api('/patient-portal/documents')).data;root.innerHTML=`${pageHeader('My documents','Private records shared with you by your healthcare provider.')}<section class="card p-5">${d.map(x=>`<div class="py-3 border-b border-line flex justify-between items-center gap-3"><div><b class="text-sm">${esc(x.originalName)}</b><p class="text-xs text-muted mt-1">${esc(x.category.replaceAll('_',' '))} · ${(x.size/1024).toFixed(1)} KB · ${new Date(x.createdAt).toLocaleDateString()}</p></div><button class="btn-secondary" data-doc="${x._id}">Download</button></div>`).join('')||'<div class="empty-state">No documents have been shared with you.</div>'}</section>`;root.querySelectorAll('[data-doc]').forEach(b=>b.onclick=async()=>{try{const r=await fetch(`${API}/patient-portal/documents/${b.dataset.doc}/download`,{headers:{Authorization:`Bearer ${state.token}`},credentials:'include'});if(!r.ok)throw new Error('Document download failed');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='careflow-document';a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message,'error')}})}
async function patientPortalNotifications(root){const d=(await api('/patient-portal/notifications')).data;root.innerHTML=`${pageHeader('Notifications','Updates from your clinic.')}<section class="card p-5">${d.map(n=>`<div class="py-3 border-b border-line flex justify-between gap-3"><div><b class="text-sm">${esc(n.title)}</b><p class="text-xs text-muted mt-1">${esc(n.message)}</p><p class="text-[10px] text-muted mt-2">${new Date(n.createdAt).toLocaleString()}</p></div>${n.readAt?'<span class="text-[10px] text-muted">Read</span>':`<button class="btn-secondary" data-read="${n._id}">Mark read</button>`}</div>`).join('')||'<div class="empty-state">No notifications yet.</div>'}</section>`;root.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{try{await api(`/patient-portal/notifications/${b.dataset.read}/read`,{method:'PATCH',body:'{}'});patientPortalNotifications(root)}catch(e){toast(e.message,'error')}})}
async function patientPortalProfile(root){const p=(await api('/patient-portal/profile')).data;root.innerHTML=`${pageHeader('My profile','View verified details and request changes to your contact information.')}<section class="card p-5 max-w-3xl"><div class="grid sm:grid-cols-2 gap-4 text-xs mb-6">${[['Patient ID',p.uhid],['Name',p.firstName+' '+p.lastName],['Date of birth',p.dob?new Date(p.dob).toLocaleDateString():'—'],['Blood group',p.bloodGroup||'—'],['Email',p.email||'—'],['Branch',p.branchId?.name||'—']].map(([k,v])=>`<div><p class="text-muted">${k}</p><b>${esc(v)}</b></div>`).join('')}</div><div class="flex justify-between items-center mb-3"><h3 class="font-bold text-sm">Request contact or address changes</h3><button type="button" id="portal-change-password" class="btn-secondary">Change password</button></div><form id="profile-request" class="field-grid"><div><label class="field-label">Mobile</label><input class="field" name="phone" value="${esc(p.phone||'')}"></div><div><label class="field-label">Alternate mobile</label><input class="field" name="alternatePhone" value="${esc(p.alternatePhone||'')}"></div><div class="full"><label class="field-label">Address</label><input class="field" name="address" value="${esc(p.address||'')}"></div><div><label class="field-label">City</label><input class="field" name="city" value="${esc(p.city||'')}"></div><div><label class="field-label">State</label><input class="field" name="state" value="${esc(p.state||'')}"></div><div><label class="field-label">Country</label><input class="field" name="country" value="${esc(p.country||'India')}"></div><div><label class="field-label">PIN code</label><input class="field" name="postalCode" value="${esc(p.postalCode||'')}"></div><div class="full border-t border-line pt-4"><p class="field-label mb-2">Communication preferences</p><div class="flex flex-wrap gap-4 text-xs"><label><input type="checkbox" name="prefEmail" ${p.communicationPreferences?.email!==false?'checked':''}> Email</label><label><input type="checkbox" name="prefSms" ${p.communicationPreferences?.sms?'checked':''}> SMS</label><label><input type="checkbox" name="prefWhatsapp" ${p.communicationPreferences?.whatsapp?'checked':''}> WhatsApp</label><label><input type="checkbox" name="prefReminders" ${p.communicationPreferences?.appointmentReminders!==false?'checked':''}> Appointment reminders</label></div></div><div class="full"><button class="btn-primary">Save profile requests & preferences</button></div></form><p class="text-xs text-muted mt-3">Verified clinical details cannot be edited from the patient portal. Requests are reviewed by clinic staff.</p></section>`;$('#portal-change-password').onclick=()=>{showModal('Change password',`<form id="portal-password-form" class="space-y-3"><div><label class="field-label">Current password</label><input class="field" name="currentPassword" type="password" required></div><div><label class="field-label">New password (12+ characters)</label><input class="field" name="newPassword" type="password" minlength="12" required></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="portal-password-form">Update password</button>');$('#portal-password-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/auth/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(ev.target)))});closeModal();toast('Password changed. Please sign in again.');logout(false)}catch(err){toast(err.message,'error')}}};$('#profile-request').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),changes=Object.fromEntries(fd);for(const k of ['prefEmail','prefSms','prefWhatsapp','prefReminders'])delete changes[k];Object.keys(changes).forEach(k=>{if(!changes[k])delete changes[k]});changes.communicationPreferences={email:fd.has('prefEmail'),sms:fd.has('prefSms'),whatsapp:fd.has('prefWhatsapp'),appointmentReminders:fd.has('prefReminders')};try{const r=await api('/patient-portal/profile',{method:'PATCH',body:JSON.stringify(changes)});toast(r.message)}catch(x){toast(x.message,'error')}}}

