 $('#doctor-search').onkeydown=e=>{if(e.key==='Enter'){state.doctorQuery=e.target.value;state.doctorPage=1;doctors(root)}};$('#doctor-status').onchange=e=>{state.doctorStatus=e.target.value;state.doctorPage=1;doctors(root)};$('#doctor-prev').onclick=()=>{state.doctorPage=Math.max(1,(state.doctorPage||1)-1);doctors(root)};$('#doctor-next').onclick=()=>{state.doctorPage=(state.doctorPage||1)+1;doctors(root)};$('#add-doctor').onclick=()=>doctorModal(null,branches.data);$('#doctor-schedules').onclick=()=>navigate('Doctor Schedules');$('#doctor-departments').onclick=()=>departmentsPage();root.querySelectorAll('[data-doctor-view]').forEach(b=>b.onclick=()=>doctorDetail(b.dataset.doctorView));root.querySelectorAll('[data-doctor-schedule]').forEach(b=>b.onclick=()=>doctorScheduleModal(b.dataset.doctorSchedule,branches.data));
