async function invoices(root){const d=(await api('/invoices')).data;root.innerHTML=`${pageHeader('Billing & invoices','Create patient invoices and record collections.','<button id="new-invoice" class="btn-primary"><i class="fa-solid fa-plus"></i> Create invoice</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Patient</th><th>Issue date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${d.map(x=>`<tr><td class="font-semibold">${esc(x.invoiceNo)}</td><td>${esc(x.patientId?.firstName)} ${esc(x.patientId?.lastName)}</td><td>${new Date(x.createdAt).toLocaleDateString()}</td><td>₹${x.total.toLocaleString('en-IN')}</td><td>₹${x.paid.toLocaleString('en-IN')}</td><td>₹${(x.total-x.paid).toLocaleString('en-IN')}</td><td><span class="pill ${x.status==='paid'?'':'warning'}">${esc(x.status)}</span></td><td>${x.status!=='paid'?`<button class="btn-secondary" data-pay="${x._id}" data-balance="${x.total-x.paid}">Record payment</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8"><div class="empty-state"><i class="fa-solid fa-file-invoice"></i><p>No invoices created yet.</p></div></td></tr>'}</tbody></table></div></section>`;$('#new-invoice').onclick=()=>invoiceModal();root.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>paymentModal(b.dataset.pay,Number(b.dataset.balance)))}
async function invoiceModal(){try{const [p,branches]=await Promise.all([api('/patients?limit=100'),api('/branches')]);if(!p.data.length){toast('Register a patient first.','error');return}showModal('Create invoice',`<form id="invoice-form" class="space-y-4"><div><label class="field-label">Branch *</label><select name="branchId" class="field" required>${branches.map(b=>`<option value="${b._id}" ${state.selectedBranch===b._id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div><label class="field-label">Patient *</label><select name="patientId" class="field">${p.data.map(x=>`<option value="${x._id}">${esc(x.firstName)} ${esc(x.lastName)} · ${esc(x.uhid)}</option>`).join('')}</select></div><div id="invoice-lines"><div class="field-grid invoice-line"><div><label class="field-label">Description</label><input class="field" name="desc" required></div><div class="grid grid-cols-2 gap-2"><div><label class="field-label">Qty</label><input class="field" name="qty" type="number" min="1" value="1"></div><div><label class="field-label">Unit price</label><input class="field" name="price" type="number" min="0" value="0"></div></div></div></div><button type="button" id="add-line" class="text-xs text-mint font-semibold"><i class="fa-solid fa-plus mr-1"></i>Add line item</button><div class="field-grid"><div><label class="field-label">Discount (₹)</label><input class="field" name="discount" type="number" min="0" value="0"></div><div><label class="field-label">Tax (₹)</label><input class="field" name="tax" type="number" min="0" value="0"></div></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="invoice-form">Save invoice</button>');const invoiceBranch=$('#invoice-form [name=branchId]'),invoicePatient=$('#invoice-form [name=patientId]');const refreshInvoicePatients=()=>{const ps=p.data.filter(x=>String(x.branchId)===invoiceBranch.value);invoicePatient.innerHTML=ps.map(x=>`<option value="${x._id}">${esc(x.firstName)} ${esc(x.lastName)} · ${esc(x.uhid)}</option>`).join('')};invoiceBranch.onchange=refreshInvoicePatients;refreshInvoicePatients();$('#add-line').onclick=()=>$('#invoice-lines').insertAdjacentHTML('beforeend',`<div class="field-grid invoice-line border-t border-line pt-3 mt-3"><div><label class="field-label">Description</label><input class="field" name="desc" required></div><div class="grid grid-cols-2 gap-2"><div><label class="field-label">Qty</label><input class="field" name="qty" type="number" min="1" value="1"></div><div><label class="field-label">Unit price</label><input class="field" name="price" type="number" min="0" value="0"></div></div></div>`);$('#invoice-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),items=[...$('#invoice-lines').querySelectorAll('.invoice-line')].map(line=>({description:line.querySelector('[name=desc]').value,quantity:Number(line.querySelector('[name=qty]').value),unitPrice:Number(line.querySelector('[name=price]').value)}));try{await api('/invoices',{method:'POST',body:JSON.stringify({patientId:f.get('patientId'),branchId:f.get('branchId'),items,discount:Number(f.get('discount')),tax:Number(f.get('tax'))})});closeModal();toast('Invoice created');navigate('Billing & Invoices')}catch(x){toast(x.message,'error')}}}catch(e){toast(e.message,'error')}}
function paymentModal(id,balance){showModal('Record payment',`<form id="payment-form" class="space-y-4"><div><label class="field-label">Outstanding balance</label><div class="text-xl font-bold">₹${balance.toLocaleString('en-IN')}</div></div><div><label class="field-label">Amount (₹) *</label><input name="amount" type="number" min="0.01" max="${balance}" step="0.01" class="field" required></div><div><label class="field-label">Payment method</label><select name="method" class="field"><option value="upi">UPI</option><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option></select></div><div><label class="field-label">Reference (optional)</label><input name="reference" class="field"></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="payment-form">Record payment</button>');$('#payment-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.amount=Number(d.amount);d.idempotencyKey=crypto.randomUUID();try{await api(`/invoices/${id}/payments`,{method:'POST',body:JSON.stringify(d)});closeModal();toast('Payment recorded');navigate('Billing & Invoices')}catch(x){toast(x.message,'error')}}}
async function labs(root){return laboratoryPage(root)}
async function radiology(root){return radiologyPage(root)}
async function admissions(root){const d=(await api('/admissions')).data;root.innerHTML=`${pageHeader('Admissions','Manage inpatient admissions and bed allocation.','<button id="new-admission" class="btn-primary"><i class="fa-solid fa-plus"></i> Admit patient</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Admission no.</th><th>Patient</th><th>Ward / Room / Bed</th><th>Admitted</th><th>Status</th></tr></thead><tbody>${d.map(x=>`<tr><td class="font-semibold">${esc(x.admissionNo)}</td><td>${esc(x.patientId?.firstName)} ${esc(x.patientId?.lastName)} · ${esc(x.patientId?.uhid)}</td><td>${esc([x.ward,x.room,x.bed].filter(Boolean).join(' / ')||'Unassigned')}</td><td>${new Date(x.admittedAt).toLocaleDateString()}</td><td><span class="pill">Admitted</span></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-state"><i class="fa-solid fa-bed"></i><p>No active admissions.</p></div></td></tr>'}</tbody></table></div></section>`;$('#new-admission').onclick=async()=>{const [p,branches]=await Promise.all([api('/patients?limit=100'),api('/branches')]);if(!p.data.length){toast('Register a patient first.','error');return}showModal('Admit patient',`<form id="admit-form" class="field-grid"><div class="full"><label class="field-label">Patient</label><select class="field" name="patientId">${p.data.map(x=>`<option value="${x._id}">${esc(x.firstName)} ${esc(x.lastName)} · ${esc(x.uhid)}</option>`).join('')}</select></div><div><label class="field-label">Ward</label><input class="field" name="ward"></div><div><label class="field-label">Room</label><input class="field" name="room"></div><div><label class="field-label">Bed</label><input class="field" name="bed"></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="admit-form">Admit patient</button>');$('#admit-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api('/admissions',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Admission created');navigate('Admissions')}catch(x){toast(x.message,'error')}}}}
async function medicines(root){const d=(await api('/medicines')).data;root.innerHTML=`${pageHeader('Medicine master','Maintain your organization medicine catalogue.','<button id="new-medicine" class="btn-primary"><i class="fa-solid fa-plus"></i> Add medicine</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Medicine</th><th>Generic name</th><th>Strength</th><th>Unit</th><th>Reorder level</th></tr></thead><tbody>${d.map(x=>`<tr><td class="font-semibold">${esc(x.name)}</td><td>${esc(x.genericName||'—')}</td><td>${esc(x.strength||'—')}</td><td>${esc(x.unit||'—')}</td><td>${x.reorderLevel}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-state"><i class="fa-solid fa-pills"></i><p>Medicine catalogue is empty.</p></div></td></tr>'}</tbody></table></div></section>`;$('#new-medicine').onclick=()=>{showModal('Add medicine',`<form id="med-form" class="field-grid"><div><label class="field-label">Medicine name *</label><input name="name" class="field" required></div><div><label class="field-label">Generic name</label><input name="genericName" class="field"></div><div><label class="field-label">Strength</label><input name="strength" class="field"></div><div><label class="field-label">Unit</label><input name="unit" class="field" placeholder="Tablet, bottle..."></div><div><label class="field-label">Reorder level</label><input name="reorderLevel" type="number" min="0" value="0" class="field"></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="med-form">Save medicine</button>');$('#med-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.reorderLevel=Number(d.reorderLevel);try{await api('/medicines',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Medicine added');navigate('Medicine Master')}catch(x){toast(x.message,'error')}}}}

async function platformDashboard(root){const d=(await api('/platform/dashboard')).data;root.innerHTML=`${pageHeader('Platform overview','SaaS-wide organization and subscription health.','<button class="btn-secondary" data-route="Organizations">Manage organizations</button>')}<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-6">${stat('Organizations',d.totalOrganizations,'fa-hospital','Registered tenants')}${stat('Active organizations',d.activeOrganizations,'fa-circle-check','Currently active')}${stat('Trial organizations',d.trialOrganizations,'fa-hourglass-half','In trial')}${stat('Suspended',d.suspendedOrganizations,'fa-ban','Access suspended')}${stat('Branches',d.totalBranches,'fa-code-branch','Across platform')}${stat('Registered users',d.totalUsers,'fa-users','All tenant accounts')}${stat('Active subscriptions',d.activeSubscriptions,'fa-credit-card','Subscription records')}${stat('Monthly recurring revenue','₹'+Number(d.mrr).toLocaleString('en-IN'),'fa-indian-rupee-sign','Configured subscription value')}</div><section class="card p-5"><h3 class="font-bold text-sm mb-2">Platform administration</h3><p class="text-xs text-muted">Organization status and subscription totals are calculated from persisted MongoDB records. MRR reflects configured subscription amounts, not payment-gateway reconciled revenue.</p></section>`;root.querySelector('[data-route]').onclick=()=>navigate('Organizations')}
async function organizationsPage(root){const r=await api('/platform/tenants');root.innerHTML=`${pageHeader('Organizations','Manage registered hospitals and clinic tenants.')}<section class="card"><div class="p-4 border-b border-line"><input id="tenant-q" class="field max-w-sm" placeholder="Search organizations"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Organization</th><th>Code</th><th>Status</th><th>Plan</th><th>Created</th><th>Action</th></tr></thead><tbody>${r.data.map(t=>`<tr><td class="font-semibold">${esc(t.name)}</td><td>${esc(t.slug)}</td><td><span class="pill ${t.status==='active'?'':'warning'}">${esc(t.status)}</span></td><td>${esc(t.plan||'starter')}</td><td>${new Date(t.createdAt).toLocaleDateString()}</td><td><select class="field max-w-[130px]" data-tenant="${t._id}"><option value="">Change status</option>${['active','trial','suspended'].map(v=>`<option value="${v}">${v}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">No organizations registered.</div></td></tr>'}</tbody></table></div></section>`;root.querySelectorAll('[data-tenant]').forEach(el=>el.onchange=async()=>{if(!el.value)return;try{await api(`/platform/tenants/${el.dataset.tenant}/status`,{method:'PATCH',body:JSON.stringify({status:el.value})});toast('Organization status updated');organizationsPage(root)}catch(e){toast(e.message,'error')}});$('#tenant-q').oninput=()=>{const q=$('#tenant-q').value.toLowerCase();root.querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q))}}


async function plansPage(root){const r=await api('/platform/plans');root.innerHTML=`${pageHeader('Subscription plans','Configure platform tiers and module entitlements.','<button id="add-plan" class="btn-primary"><i class="fa-solid fa-plus"></i> Add plan</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Plan</th><th>Key</th><th>Monthly price</th><th>Limits</th><th>Modules</th></tr></thead><tbody>${r.data.map(p=>`<tr><td class="font-semibold">${esc(p.name)}</td><td>${esc(p.key)}</td><td>₹${Number(p.monthlyAmount).toLocaleString('en-IN')}</td><td>${esc(JSON.stringify(p.limits))}</td><td>${esc((p.modules||[]).join(', '))}</td></tr>`).join('')||'<tr><td colspan="5">No plans configured.</td></tr>'}</tbody></table></div></section>`;$('#add-plan').onclick=()=>showModal('Create subscription plan',`<form id="plan-form" class="space-y-3"><div><label class="field-label">Plan name</label><input class="field" name="name" required></div><div><label class="field-label">Plan key</label><input class="field" name="key" required pattern="[a-z0-9_-]+"></div><div><label class="field-label">Monthly amount (₹)</label><input class="field" name="monthlyAmount" type="number" min="0" value="0" required></div><div><label class="field-label">Branch limit</label><input class="field" name="branches" type="number" min="1" value="1"></div><div><label class="field-label">User limit</label><input class="field" name="users" type="number" min="1" value="5"></div><div><label class="field-label">Modules (comma separated)</label><input class="field" name="modules" placeholder="patients,appointments,billing"></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="plan-form">Save plan</button>');$('#plan-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/platform/plans',{method:'POST',body:JSON.stringify({name:f.get('name'),key:f.get('key'),monthlyAmount:Number(f.get('monthlyAmount')),limits:{branches:Number(f.get('branches')),users:Number(f.get('users'))},modules:f.get('modules').split(',').map(v=>v.trim()).filter(Boolean)})});closeModal();toast('Plan created');plansPage(root)}catch(x){toast(x.message,'error')}}}

async function subscriptionsPage(root){const r=await api('/platform/subscriptions');root.innerHTML=`${pageHeader('Subscriptions','Subscription status and configured plan value.')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Organization</th><th>Plan</th><th>Status</th><th>Monthly amount</th><th>Started</th><th>Ends</th></tr></thead><tbody>${r.data.map(s=>`<tr><td class="font-semibold">${esc(s.tenantId?.name||'Unknown tenant')}</td><td>${esc(s.plan)}</td><td>${esc(s.status)}</td><td>₹${Number(s.monthlyAmount||0).toLocaleString('en-IN')}</td><td>${new Date(s.startedAt).toLocaleDateString()}</td><td>${s.endsAt?new Date(s.endsAt).toLocaleDateString():'—'}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">No subscription records.</div></td></tr>'}</tbody></table></div></section>`}
async function platformUsersPage(root){const r=await api('/platform/users');root.innerHTML=`${pageHeader('Platform users','Super Admin accounts and platform-level access.')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Last login</th></tr></thead><tbody>${r.data.map(u=>`<tr><td class="font-semibold">${esc(u.name)}</td><td>${esc(u.email)}</td><td>${u.active?'Active':'Inactive'}</td><td>${u.lastLoginAt?new Date(u.lastLoginAt).toLocaleString():'—'}</td></tr>`).join('')||'<tr><td colspan="4">No platform users.</td></tr>'}</tbody></table></div></section>`}

async function branchesPage(root){const r=await api('/branches');root.innerHTML=`${pageHeader('Branches','Manage locations, branch codes and operating details.','<button id="add-branch" class="btn-primary"><i class="fa-solid fa-plus"></i> Add branch</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Branch</th><th>Code</th><th>Location</th><th>Manager</th><th>Doctors</th><th>Staff</th><th>Status</th><th></th></tr></thead><tbody>${r.data.map(b=>`<tr><td class="font-semibold">${esc(b.name)}</td><td>${esc(b.code)}</td><td>${esc([b.city,b.state].filter(Boolean).join(', ')||b.address||'—')}</td><td>${esc(b.managerName||'—')}</td><td>${b.doctorCount}</td><td>${b.staffCount}</td><td><span class="pill ${b.active?'':'danger'}">${b.active?'Active':'Inactive'}</span></td><td><button class="btn-secondary" data-edit-branch="${b._id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty-state">No branches found.</div></td></tr>'}</tbody></table></div></section>`;$('#add-branch').onclick=()=>branchModal();root.querySelectorAll('[data-edit-branch]').forEach(b=>b.onclick=()=>branchModal(r.data.find(x=>x._id===b.dataset.editBranch)))}
function branchModal(b={}){showModal(b._id?'Edit branch':'Add branch',`<form id="branch-form" class="field-grid"><div><label class="field-label">Branch name *</label><input class="field" name="name" required value="${esc(b.name||'')}"></div><div><label class="field-label">Branch code *</label><input class="field" name="code" required ${b._id?'disabled':''} value="${esc(b.code||'')}"></div><div><label class="field-label">City</label><input class="field" name="city" value="${esc(b.city||'')}"></div><div><label class="field-label">State</label><input class="field" name="state" value="${esc(b.state||'')}"></div><div><label class="field-label">Phone</label><input class="field" name="phone" value="${esc(b.phone||'')}"></div><div><label class="field-label">Email</label><input class="field" name="email" type="email" value="${esc(b.email||'')}"></div><div><label class="field-label">Branch manager</label><input class="field" name="managerName" value="${esc(b.managerName||'')}"></div><div><label class="field-label">Timezone</label><input class="field" name="timezone" value="${esc(b.timezone||'Asia/Kolkata')}"></div><div class="full"><label class="field-label">Address</label><input class="field" name="address" value="${esc(b.address||'')}"></div>${b._id?`<label class="flex items-center gap-2 text-xs"><input type="checkbox" name="active" ${b.active?'checked':''}> Branch active</label>`:''}</form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="branch-form">Save branch</button>');$('#branch-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),d=Object.fromEntries(f);if(b._id)d.active=f.has('active');try{await api(b._id?`/branches/${b._id}`:'/branches',{method:b._id?'PATCH':'POST',body:JSON.stringify(d)});closeModal();toast('Branch saved');navigate('Branches & Departments')}catch(x){toast(x.message,'error')}}}
async function usersPage(root){const r=await api('/users?limit=100');root.innerHTML=`${pageHeader('Users & roles','Manage staff accounts, branch assignments and access.','<button id="add-user" class="btn-primary"><i class="fa-solid fa-user-plus"></i> Add user</button>')}<section class="card"><div class="p-4 border-b border-line"><input id="user-q" class="field max-w-sm" placeholder="Search name or email"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Branches</th><th>Status</th><th></th></tr></thead><tbody>${r.data.map(u=>`<tr><td class="font-semibold">${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role.replaceAll('_',' '))}</td><td>${u.branchIds.length}</td><td><span class="pill ${u.active?'':'danger'}">${u.active?'Active':'Inactive'}</span></td><td><button class="btn-secondary" data-edit-user="${u.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">No users found.</div></td></tr>'}</tbody></table></div></section><section class="mt-5"><button class="btn-secondary" id="manage-roles">Manage custom roles & permissions</button></section>`;$('#add-user').onclick=()=>userModal();$('#manage-roles').onclick=()=>rolesPage(root);$('#user-q').oninput=()=>{const q=$('#user-q').value.toLowerCase();root.querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q))};root.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>userModal(r.data.find(u=>u.id===b.dataset.editUser)))}
async function userModal(u){const br=(await api('/branches')).data;const roles=state.user.role==='hospital_admin'?['branch_admin','doctor','receptionist','nurse','pharmacist','lab_technician','accountant']:['doctor','receptionist','nurse','pharmacist','lab_technician','accountant'];showModal(u?'Edit user':'Create user',`<form id="user-form" class="field-grid"><div><label class="field-label">Full name *</label><input name="name" class="field" required value="${esc(u?.name||'')}"></div><div><label class="field-label">Email *</label><input name="email" type="email" class="field" required ${u?'disabled':''} value="${esc(u?.email||'')}"></div>${u?'':`<div class="full"><label class="field-label">Temporary password (min 12 characters)</label><input name="password" type="password" minlength="12" class="field" required></div>`}<div><label class="field-label">Role</label><select name="role" class="field">${roles.map(v=>`<option value="${v}" ${u?.role===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></div><div class="full"><label class="field-label">Branch access</label><div class="grid grid-cols-2 gap-2">${br.map(b=>`<label class="text-xs flex gap-2 items-center"><input type="checkbox" name="branchIds" value="${b._id}" ${(u?.branchIds||[]).includes(b._id)?'checked':''}>${esc(b.name)}</label>`).join('')}</div></div>${u?`<label class="flex gap-2 items-center text-xs"><input type="checkbox" name="active" ${u.active?'checked':''}> Account active</label>`:''}</form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="user-form">Save user</button>');$('#user-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),d={name:f.get('name'),role:f.get('role'),branchIds:f.getAll('branchIds')};if(!u){d.email=f.get('email');d.password=f.get('password')}else d.active=f.has('active');try{await api(u?`/users/${u.id}`:'/users',{method:u?'PATCH':'POST',body:JSON.stringify(d)});closeModal();toast('User saved');navigate('Users & Roles')}catch(x){toast(x.message,'error')}}}
async function rolesPage(root){const r=await api('/roles');root.innerHTML=`${pageHeader('Custom roles & permissions','Create reusable access profiles for your organization.','<button id="new-role" class="btn-primary"><i class="fa-solid fa-plus"></i> Create role</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Role</th><th>Key</th><th>Permissions</th><th>Type</th></tr></thead><tbody>${r.data.map(v=>`<tr><td class="font-semibold">${esc(v.name)}</td><td>${esc(v.key)}</td><td>${v.permissions.length}</td><td>${v.system?'System':'Custom'}</td></tr>`).join('')||'<tr><td colspan="4">No custom roles created yet.</td></tr>'}</tbody></table></div></section>`;$('#new-role').onclick=()=>showModal('Create custom role',`<form id="role-form" class="space-y-3"><div><label class="field-label">Role name</label><input class="field" name="name" required></div><div><label class="field-label">Role key (unique)</label><input class="field" name="key" required pattern="[a-zA-Z0-9_-]+"></div><div><label class="field-label">Description</label><input class="field" name="description"></div><div class="border rounded-lg p-3 max-h-64 overflow-auto"><div class="font-semibold text-xs mb-2">Permissions</div><div class="grid sm:grid-cols-2 gap-2">${r.availablePermissions.map(v=>`<label class="text-xs flex items-center gap-2"><input type="checkbox" name="permissions" value="${v}">${v}</label>`).join('')}</div></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="role-form">Create role</button>');$('#role-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/roles',{method:'POST',body:JSON.stringify({name:f.get('name'),key:f.get('key'),description:f.get('description'),permissions:f.getAll('permissions')})});closeModal();toast('Role created');rolesPage(root)}catch(x){toast(x.message,'error')}}}
async function auditPage(root,platform){const r=await api(platform?'/platform/audit-logs':'/audit-logs');root.innerHTML=`${pageHeader(platform?'Platform audit logs':'Audit logs','Read-only history of sensitive account and organization actions.')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Resource</th><th>Record</th><th>IP</th></tr></thead><tbody>${r.data.map(a=>`<tr><td>${new Date(a.createdAt).toLocaleString()}</td><td>${esc(a.userId?.name||'System')}</td><td>${esc(a.action)}</td><td>${esc(a.resource||'—')}</td><td>${esc(a.resourceId||'—')}</td><td>${esc(a.ip||'—')}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">No audit events recorded.</div></td></tr>'}</tbody></table></div></section>`}
async function settingsPage(root){if(state.user.role==='super_admin'){root.innerHTML=`${pageHeader('Platform settings','Global configuration controls.')}<section class="card p-5"><p class="text-sm font-semibold">Platform configuration</p><p class="text-xs text-muted mt-2">System settings are intentionally restricted to server-side configuration until an audited settings schema and change policy are configured.</p></section>`;return}const t=(await api('/tenant')).data;root.innerHTML=`${pageHeader('Organization settings','Manage organization profile and preferences.')}<section class="card p-5 max-w-2xl"><form id="tenant-form" class="space-y-4"><div><label class="field-label">Organization name</label><input class="field" name="name" value="${esc(t.name)}" required></div><div><label class="field-label">Workspace status</label><div class="text-xs text-muted">${esc(t.status)}</div></div><button class="btn-primary">Save settings</button></form></section><section class="card p-5 max-w-2xl mt-5"><h3 class="font-semibold text-sm mb-3">Security</h3><button id="change-password" class="btn-secondary">Change password</button> <button id="view-sessions" class="btn-secondary">Manage sessions</button></section>`;$('#change-password').onclick=()=>showModal('Change password',`<form id="change-password-form" class="space-y-3"><div><label class="field-label">Current password</label><input name="currentPassword" type="password" class="field" required></div><div><label class="field-label">New password (12+ characters)</label><input name="newPassword" type="password" class="field" minlength="12" required></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="change-password-form">Update password</button>');$('#change-password-form').onsubmit=async e=>{e.preventDefault();try{await api('/auth/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Password changed. Sign in again.');logout(false)}catch(x){toast(x.message,'error')}};$('#view-sessions').onclick=async()=>{try{const r=await api('/auth/sessions');showModal('Active sessions',r.data.map(s=>`<div class="flex justify-between items-center border-b border-line py-2 text-xs gap-3"><span>${new Date(s.createdAt).toLocaleString()} · expires ${new Date(s.expiresAt).toLocaleString()}</span><button class="btn-secondary" data-revoke-session="${s._id}">Revoke</button></div>`).join('')||'No active sessions.','<button class="btn-secondary" data-close>Close</button>');$('#modal-root').querySelectorAll('[data-revoke-session]').forEach(b=>b.onclick=async()=>{try{await api('/auth/sessions/'+b.dataset.revokeSession,{method:'DELETE'});toast('Session revoked');b.closest('div.flex').remove()}catch(x){toast(x.message,'error')}})}catch(x){toast(x.message,'error')}};$('#tenant-form').onsubmit=async e=>{e.preventDefault();try{await api('/tenant',{method:'PATCH',body:JSON.stringify({name:new FormData(e.target).get('name')})});toast('Organization settings saved')}catch(x){toast(x.message,'error')}}}

async function consultations(root){const result=await api('/consultations?limit=100'),d=result.data||[];root.innerHTML=`${pageHeader('Consultations','Clinical encounters, draft notes and finalized records.','<button id="new-consult" class="btn-primary"><i class="fa-solid fa-plus"></i> Start consultation</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Patient</th><th>Doctor</th><th>Chief complaint</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody>${d.map(x=>`<tr><td class="font-semibold">${esc(x.patientId?.firstName)} ${esc(x.patientId?.lastName)}<div class="text-[10px] text-muted">${esc(x.patientId?.uhid||'')}</div></td><td>${esc(x.doctorId?.name||'—')}</td><td>${esc(x.chiefComplaint||'—')}</td><td><span class="pill ${['finalized','amended'].includes(x.status)?'':'warning'}">${esc(x.status)}</span></td><td>${new Date(x.createdAt).toLocaleDateString()}</td><td><button class="btn-secondary" data-open-consult="${x._id}">Open</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state"><i class="fa-solid fa-stethoscope"></i><p>No consultations recorded.</p></div></td></tr>'}</tbody></table></div></section>`;$('#new-consult').onclick=()=>newConsultationModal();root.querySelectorAll('[data-open-consult]').forEach(b=>b.onclick=()=>consultationDetail(b.dataset.openConsult));}
async function newConsultationModal(patientId='',appointmentId='',doctorId=''){const [p,d,t]=await Promise.all([api('/patients?limit=100'),api('/doctors?limit=100'),api('/clinical-templates').catch(()=>({data:[]}))]);const patients=p.data||[],doctors=d.data||[],templates=t.data||[];if(!patients.length||!doctors.length){toast('Add an accessible patient and doctor first.','error');return}showModal('Start consultation',`<form id="consult-form" class="field-grid"><div class="full"><label class="field-label">Patient</label><select class="field" name="patientId">${patients.map(x=>`<option value="${x._id}" ${patientId===x._id?'selected':''}>${esc(x.firstName)} ${esc(x.lastName)} · ${esc(x.uhid)}</option>`).join('')}</select></div><div class="full"><label class="field-label">Doctor</label><select class="field" name="doctorId">${doctors.map(x=>`<option value="${x._id}" ${doctorId===x._id?'selected':''}>${esc(x.name)} · ${esc(x.specialty||'')}</option>`).join('')}</select></div><div class="full"><label class="field-label">Clinical note template (optional)</label><select class="field" name="templateId"><option value="">General consultation</option>${templates.map(t=>`<option value="${t._id}">${esc(t.name)} · ${esc(t.type)}</option>`).join('')}</select></div><div class="full"><label class="field-label">Appointment ID (optional)</label><input class="field" name="appointmentId" value="${esc(appointmentId)}" placeholder="Link an existing appointment ID"></div><div class="full"><label class="field-label">Chief complaint</label><input class="field" name="chiefComplaint" maxlength="2000"></div><div class="full"><label class="field-label">History of present illness</label><textarea class="field h-20 py-3" name="historyOfPresentIllness"></textarea></div><div class="full"><label class="field-label">Examination findings</label><textarea class="field h-20 py-3" name="examination"></textarea></div><div class="full"><label class="field-label">Assessment / clinical impression</label><textarea class="field h-20 py-3" name="assessment"></textarea></div><div class="full"><label class="field-label">Plan and recommendations</label><textarea class="field h-20 py-3" name="plan"></textarea></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="consult-form">Save draft</button>');$('#consult-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.appointmentId)delete f.appointmentId;if(!f.templateId)delete f.templateId;try{const r=await api('/consultations',{method:'POST',body:JSON.stringify(f)});closeModal();toast('Consultation draft created');await consultationDetail(r.data._id)}catch(x){toast(x.message,'error')}}}
async function consultationDetail(id){try{const r=(await api(`/consultations/${id}`)).data,c=r.consultation,p=c.patientId;showModal('Consultation workspace',`<div class="space-y-4 text-xs"><div class="rounded-xl bg-[#F4F7F6] p-4"><div class="font-bold text-base">${esc(p.firstName)} ${esc(p.lastName)}</div><div class="text-muted mt-1">${esc(p.uhid)} · ${esc(p.sex||'')} · ${p.dob?new Date(p.dob).toLocaleDateString():''}</div><div class="mt-2">Allergies: ${esc((p.allergies||[]).join(', ')||'Not recorded')}</div><div>Current medications: ${esc((p.currentMedications||[]).join(', ')||'Not recorded')}</div><div>Medical history records: ${r.history.length} · Recent vitals: ${r.vitals.length}</div></div><div class="grid sm:grid-cols-2 gap-3">${[['Chief complaint',c.chiefComplaint],['History',c.historyOfPresentIllness||c.history],['Past medical history',c.pastMedicalHistory],['Review of systems',c.reviewOfSystems],['Examination',c.examination],['Assessment',c.assessment],['Clinical impression',c.clinicalImpression],['Plan',c.plan],['Doctor notes',c.notes],['Follow-up',c.followUpRecommendations]].map(([k,v])=>`<div class="border border-line rounded-xl p-3"><div class="text-muted mb-1">${k}</div><div class="whitespace-pre-wrap">${esc(v||'—')}</div></div>`).join('')}</div><div class="flex flex-wrap gap-2"><button class="btn-secondary" id="edit-consult" ${['finalized','amended'].includes(c.status)?'disabled':''}>Edit draft</button><button class="btn-primary" id="finalize-consult" ${['finalized','amended'].includes(c.status)?'disabled':''}>Finalize consultation</button><button class="btn-secondary" id="new-vital-from-consult">Record vitals</button><button class="btn-secondary" id="new-diagnosis-from-consult">Add diagnosis</button><button class="btn-secondary" id="new-rx-from-consult">Create prescription</button><button class="btn-secondary" id="new-lab-from-consult">Order lab tests</button><button class="btn-secondary" id="new-rad-from-consult">Order imaging</button></div>${c.amendments?.length?`<div class="border-t border-line pt-3"><b>Amendment history</b>${c.amendments.map(a=>`<p class="mt-2">v${a.version} · ${esc(a.reason)} · ${new Date(a.amendedAt).toLocaleString()}</p>`).join('')}</div>`:''}</div>`,'<button class="btn-secondary" data-close>Close</button>');$('#finalize-consult')?.addEventListener('click',async()=>{if(!confirm('Finalize this consultation? The record will become immutable except through a documented amendment.'))return;try{await api(`/consultations/${id}/finalize`,{method:'POST',body:'{}'});toast('Consultation finalized');closeModal();consultationDetail(id)}catch(e){toast(e.message,'error')}});$('#edit-consult')?.addEventListener('click',()=>editConsultation(c));$('#new-vital-from-consult')?.addEventListener('click',()=>vitalModal(p._id,id));$('#new-diagnosis-from-consult')?.addEventListener('click',()=>diagnosisModal(p._id,id));$('#new-rx-from-consult')?.addEventListener('click',()=>prescriptionModal(p._id,id));$('#new-lab-from-consult')?.addEventListener('click',()=>consultationLabOrderModal(p._id,id));$('#new-rad-from-consult')?.addEventListener('click',()=>consultationRadiologyOrderModal(p._id,id));}catch(e){toast(e.message,'error')}}
function editConsultation(c){showModal('Edit consultation draft',`<form id="edit-consult-form" class="field-grid">${[['chiefComplaint','Chief complaint'],['historyOfPresentIllness','History of present illness'],['pastMedicalHistory','Past medical history'],['familyHistory','Family history'],['reviewOfSystems','Review of systems'],['examination','Examination'],['assessment','Assessment'],['clinicalImpression','Clinical impression'],['plan','Plan'],['notes','Doctor notes']].map(([k,l])=>`<div class="full"><label class="field-label">${l}</label><textarea class="field h-20 py-3" name="${k}">${esc(c[k]||'')}</textarea></div>`).join('')}</form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="edit-consult-form">Save changes</button>');$('#edit-consult-form').onsubmit=async e=>{e.preventDefault();try{await api(`/consultations/${c._id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Draft updated');closeModal();consultationDetail(c._id)}catch(x){toast(x.message,'error')}}}
async function medicalRecords(root){const p=(await api('/patients?limit=100')).data||[];root.innerHTML=`${pageHeader('Patient EMR','Longitudinal records, history, vitals, diagnoses, plans and released documents.')}<section class="card p-4"><div class="flex flex-wrap gap-3 items-center"><select id="emr-patient" class="field flex-1 min-w-[240px]"><option value="">Select a patient to open their EMR</option>${p.map(x=>`<option value="${x._id}">${esc(x.firstName)} ${esc(x.lastName)} · ${esc(x.uhid)}</option>`).join('')}</select><button id="emr-open" class="btn-primary">Open medical record</button></div></section><div id="emr-content" class="mt-4"></div>`;$('#emr-open').onclick=()=>loadEmr($('#emr-patient').value);$('#emr-patient').onchange=()=>{if($('#emr-patient').value)loadEmr($('#emr-patient').value)}}
async function loadEmr(id){if(!id)return;const root=$('#emr-content');root.innerHTML=window.cfSkeleton?window.cfSkeleton('compact'):'<div class="card p-6 text-sm text-muted">Loading patient record…</div>';try{const d=(await api(`/patients/${id}/emr`)).data,p=d.patient;root.innerHTML=`<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-3 mb-4">${stat('Consultations',d.consultations.length,'fa-stethoscope','Finalized records')}${stat('Diagnoses',d.diagnoses.length,'fa-notes-medical','Recorded diagnoses')}${stat('Vitals',d.vitals.length,'fa-heart-pulse','Measurements')}${stat('Prescriptions',d.prescriptions.length,'fa-prescription','Issued prescriptions')}</div><section class="card p-5 mb-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="font-bold text-lg">${esc(p.firstName)} ${esc(p.lastName)}</h2><p class="text-xs text-muted mt-1">${esc(p.uhid)} · ${esc(p.sex)} · ${p.dob?new Date(p.dob).toLocaleDateString():''}</p></div><div class="flex flex-wrap gap-2"><button class="btn-secondary" id="emr-vital">Record vitals</button><button class="btn-secondary" id="emr-diagnosis">Add diagnosis</button><button class="btn-primary" id="emr-consult">Start consultation</button></div></div><div class="grid md:grid-cols-3 gap-4 mt-5 text-xs"><div><b>Allergies</b><p class="mt-1 text-muted">${esc((p.allergies||[]).join(', ')||'Not recorded')}</p></div><div><b>Chronic conditions</b><p class="mt-1 text-muted">${esc((p.conditions||[]).join(', ')||'Not recorded')}</p></div><div><b>Current medications</b><p class="mt-1 text-muted">${esc((p.currentMedications||[]).join(', ')||'Not recorded')}</p></div><div><b>Previous surgeries</b><p class="mt-1 text-muted">${esc((p.previousSurgeries||[]).join(', ')||'Not recorded')}</p></div><div><b>Family history</b><p class="mt-1 text-muted">${esc(p.familyHistory||'Not recorded')}</p></div></div></section><section class="card p-4 mb-4"><h3 class="font-bold mb-3">Patient portal release controls</h3><p class="text-xs text-muted mb-3">Only release records after clinical review and according to clinic policy. Laboratory reports are released from the Laboratory results workflow.</p><div class="space-y-2">${[['Consultation',d.consultations,'consultation'],['Diagnosis',d.diagnoses,'diagnosis'],['Treatment plan',d.treatmentPlans,'treatment'],['Medical document',d.documents,'document'],['Medical history',d.history,'history']].map(([label,items,kind])=>items.map(x=>`<div class="flex flex-wrap items-center justify-between gap-2 border-t border-line py-2 text-xs"><span>${esc(label)} · ${esc(x.chiefComplaint||x.description||x.instructions||x.originalName||x.title||x.prescriptionNo||x._id)} </span><button class="btn-secondary" data-emr-release="${kind}" data-id="${x._id}" data-value="${x.releasedToPatient||x.patientVisible?'true':'false'}">${x.releasedToPatient||x.patientVisible?'Withdraw release':'Release to patient'}</button></div>`).join('')).join('')||'<p class="text-xs text-muted">No releasable records available.</p>'}</div></section><section class="card p-4 mb-4"><h3 class="font-bold mb-3">Vital signs trend</h3><div class="grid md:grid-cols-3 gap-3"><div><p class="text-xs text-muted mb-2">Weight (kg)</p><canvas id="emr-weight-chart" height="100"></canvas></div><div><p class="text-xs text-muted mb-2">Heart rate (bpm)</p><canvas id="emr-heart-chart" height="100"></canvas></div><div><p class="text-xs text-muted mb-2">BMI</p><canvas id="emr-bmi-chart" height="100"></canvas></div></div></section><div class="grid xl:grid-cols-2 gap-4">${[['Medical history',d.history.map(x=>`${x.category}: ${x.title} — ${x.details||''} (${new Date(x.recordedAt).toLocaleDateString()})`)],['Consultations',d.consultations.map(x=>`${new Date(x.createdAt).toLocaleDateString()} · ${x.doctorId?.name||''} · ${x.chiefComplaint||x.assessment||'Clinical encounter'}`)],['Diagnoses',d.diagnoses.map(x=>`${x.code||'Custom'} · ${x.description} · ${x.type} · ${x.certainty}`)],['Vital signs',d.vitals.map(x=>`${new Date(x.measuredAt).toLocaleString()} · BP ${x.bloodPressure?.systolic||'—'}/${x.bloodPressure?.diastolic||'—'} · HR ${x.heartRate??'—'} · SpO₂ ${x.spo2??'—'} · BMI ${x.bmi??'—'}`)],['Treatment plans',d.treatmentPlans.map(x=>`${x.status} · ${x.instructions||x.notes||'Treatment plan'} · Follow-up ${x.followUpAt?new Date(x.followUpAt).toLocaleDateString():'—'}`)],['Prescriptions',d.prescriptions.map(x=>`${x.prescriptionNo||x._id} · ${x.status} · ${(x.items||[]).map(i=>i.medicine).join(', ')}`)],['Lab reports',d.laboratoryResults.map(x=>`${new Date(x.verifiedAt||x.createdAt).toLocaleDateString()} · ${(x.tests||[]).map(t=>t.name).join(', ')} · Verified`)],['Documents',d.documents.map(x=>`${x.category} · ${x.originalName} · ${x.releasedToPatient?'Released to patient':'Staff record'}`)]].map(([title,items])=>`<section class="card p-4"><h3 class="font-bold mb-3">${title}</h3>${items.length?items.map(x=>`<div class="py-2 border-t border-line text-xs">${esc(x)}</div>`).join(''):'<p class="text-xs text-muted">No records available.</p>'}</section>`).join('')}</div>`;if(window.Chart&&d.vitals.length){const points=[...d.vitals].reverse(),labels=points.map(x=>new Date(x.measuredAt).toLocaleDateString());[['emr-weight-chart','Weight (kg)','weightKg'],['emr-heart-chart','Heart rate (bpm)','heartRate'],['emr-bmi-chart','BMI','bmi']].forEach(([id,label,key])=>{const el=$('#'+id);if(!el)return;const chart=new Chart(el,{type:'line',data:{labels,datasets:[{label,data:points.map(x=>x[key]??null),spanGaps:true,tension:.25}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:false}}}});state.charts.push(chart)})}root.querySelectorAll('[data-emr-release]').forEach(b=>b.onclick=async()=>{const kind=b.dataset.emrRelease,endpoint={consultation:`/consultations/${b.dataset.id}/release`,diagnosis:`/diagnoses/${b.dataset.id}/release`,treatment:`/treatment-plans/${b.dataset.id}/release`,document:`/patients/${id}/documents/${b.dataset.id}/release`,history:`/patients/${id}/medical-history/${b.dataset.id}/visibility`}[kind],field=kind==='history'?'patientVisible':'releasedToPatient';try{await api(endpoint,{method:'PATCH',body:JSON.stringify({[field]:b.dataset.value!=='true'})});toast('Patient visibility updated');loadEmr(id)}catch(e){toast(e.message,'error')}});$('#emr-vital').onclick=()=>vitalModal(id);$('#emr-diagnosis').onclick=()=>diagnosisModal(id);$('#emr-consult').onclick=()=>newConsultationModal(id)}catch(e){root.innerHTML=`<div class="card p-5 text-sm text-rose-600">${esc(e.message)}</div>`}}
function vitalModal(patientId,consultationId=''){showModal('Record vital signs',`<form id="vital-form" class="field-grid"><div><label class="field-label">Systolic BP (mmHg)</label><input class="field" type="number" name="systolic" min="40" max="300"></div><div><label class="field-label">Diastolic BP (mmHg)</label><input class="field" type="number" name="diastolic" min="20" max="200"></div>${[['heartRate','Heart rate (bpm)',0,300],['respiratoryRate','Respiratory rate',0,100],['temperatureC','Temperature (°C)',25,45],['spo2','SpO₂ (%)',0,100],['heightCm','Height (cm)',20,280],['weightKg','Weight (kg)',.2,500],['painScore','Pain score (0–10)',0,10]].map(([n,l,min,max])=>`<div><label class="field-label">${l}</label><input class="field" name="${n}" type="number" step="any" min="${min}" max="${max}"></div>`).join('')}<div class="full"><label class="field-label">Blood glucose (mg/dL)</label><input class="field" name="glucose" type="number" min="0" max="2000"></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="vital-form">Save measurements</button>');$('#vital-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),v={};for(const [k,val] of f.entries())if(val!=='')v[k]=Number(val);const body={bloodPressure:{systolic:v.systolic,diastolic:v.diastolic},heartRate:v.heartRate,respiratoryRate:v.respiratoryRate,temperatureC:v.temperatureC,spo2:v.spo2,heightCm:v.heightCm,weightKg:v.weightKg,painScore:v.painScore};if(v.glucose!==undefined)body.bloodGlucose={value:v.glucose,unit:'mg/dL'};if(consultationId)body.consultationId=consultationId;try{await api(`/patients/${patientId}/vitals`,{method:'POST',body:JSON.stringify(body)});closeModal();toast('Vital signs saved');loadEmr(patientId)}catch(x){toast(x.message,'error')}}}
function diagnosisModal(patientId,consultationId=''){showModal('Add diagnosis',`<form id="diagnosis-form" class="field-grid"><div class="full"><label class="field-label">Diagnosis description *</label><input class="field" name="description" required maxlength="500"></div><div class="full"><label class="field-label">Search configured diagnosis catalogue</label><div class="flex gap-2"><input class="field" id="dx-catalogue-search" placeholder="Search code or description"><button type="button" class="btn-secondary" id="dx-catalogue-find">Search</button></div><select class="field mt-2" id="dx-catalogue-results"><option value="">No catalogue result selected</option></select></div><div><label class="field-label">Code (optional)</label><input class="field" name="code"></div><div><label class="field-label">Coding system</label><select class="field" name="system"><option value="custom">Custom</option><option value="ICD-10">ICD-10 (configured catalogue)</option></select></div><div><label class="field-label">Classification</label><select class="field" name="type"><option value="primary">Primary</option><option value="secondary">Secondary</option><option value="differential">Differential</option></select></div><div><label class="field-label">Certainty</label><select class="field" name="certainty"><option value="provisional">Provisional</option><option value="confirmed">Confirmed</option></select></div><div class="full"><label class="field-label">Clinical notes</label><textarea class="field h-20 py-3" name="notes"></textarea></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="diagnosis-form">Save diagnosis</button>');$('#dx-catalogue-find').onclick=async()=>{try{const q=encodeURIComponent($('#dx-catalogue-search').value.trim());const items=(await api('/diagnoses/catalogue?q='+q)).data;$('#dx-catalogue-results').innerHTML='<option value="">Select a configured code</option>'+items.map(x=>`<option value="${esc(x._id)}" data-code="${esc(x.code)}" data-description="${esc(x.description)}">${esc(x.code)} · ${esc(x.description)}</option>`).join('');if(!items.length)toast('No configured catalogue entries found','error')}catch(x){toast(x.message,'error')}};$('#dx-catalogue-results').onchange=e=>{const o=e.target.selectedOptions[0];if(!o?.dataset.code)return;$('#diagnosis-form').elements.code.value=o.dataset.code;$('#diagnosis-form').elements.description.value=o.dataset.description;$('#diagnosis-form').elements.system.value='ICD-10'};$('#diagnosis-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(consultationId)b.consultationId=consultationId;try{await api(`/patients/${patientId}/diagnoses`,{method:'POST',body:JSON.stringify(b)});closeModal();toast('Diagnosis recorded');loadEmr(patientId)}catch(x){toast(x.message,'error')}}}
async function prescriptionsPage(root){const d=(await api('/prescriptions')).data||[];root.innerHTML=`${pageHeader('Digital prescriptions','Create drafts, issue immutable prescriptions and download private PDFs.','<button id="new-rx" class="btn-primary"><i class="fa-solid fa-plus"></i> New prescription</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Prescription</th><th>Patient</th><th>Doctor</th><th>Medicines</th><th>Status</th><th></th></tr></thead><tbody>${d.map(x=>`<tr><td>${esc(x.prescriptionNo||String(x._id).slice(-8))}<div class="text-[10px] text-muted">${new Date(x.createdAt).toLocaleDateString()}</div></td><td>${esc(x.patientId?.firstName)} ${esc(x.patientId?.lastName)}</td><td>${esc(x.doctorId?.name||'—')}</td><td>${(x.items||[]).length}</td><td><span class="pill ${x.status==='draft'?'warning':''}">${esc(x.status)}</span></td><td><div class="flex gap-1"><button class="btn-secondary" data-rx-final="${x._id}" ${x.status!=='draft'?'disabled':''}>Issue</button><button class="btn-secondary" data-rx-pdf="${x._id}" ${x.status==='draft'?'disabled':''}>PDF</button></div></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state"><i class="fa-solid fa-prescription"></i><p>No prescriptions found.</p></div></td></tr>'}</tbody></table></div></section>`;$('#new-rx').onclick=()=>prescriptionModal();root.querySelectorAll('[data-rx-final]').forEach(b=>b.onclick=async()=>{if(!confirm('Issue this prescription? Finalized prescriptions cannot be silently edited.'))return;try{await api(`/prescriptions/${b.dataset.rxFinal}/finalize`,{method:'POST',body:'{}'});toast('Prescription issued');prescriptionsPage(root)}catch(e){toast(e.message,'error')}});root.querySelectorAll('[data-rx-pdf]').forEach(b=>b.onclick=()=>downloadPrescriptionPdf(b.dataset.rxPdf))}
async function prescriptionModal(patientId='',consultationId=''){const [p,d,m]=await Promise.all([api('/patients?limit=100'),api('/doctors?limit=100'),api('/medicines?limit=100')]);const patients=p.data||[],doctors=d.data||[],meds=m.data||[];if(!patients.length||!doctors.length){toast('An accessible patient and doctor are required.','error');return}const medOptions=meds.map(x=>`<option value="${x._id}" data-name="${esc(x.name)}" data-generic="${esc(x.genericName||'')}" data-strength="${esc(x.strength||'')}">${esc(x.name)} · ${esc(x.strength||'')}</option>`).join('');showModal('Create digital prescription',`<form id="rx-form" class="space-y-4"><div class="grid sm:grid-cols-2 gap-3"><div><label class="field-label">Patient</label><select class="field" name="patientId">${patients.map(x=>`<option value="${x._id}" ${patientId===x._id?'selected':''}>${esc(x.firstName)} ${esc(x.lastName)} · ${esc(x.uhid)}</option>`).join('')}</select></div><div><label class="field-label">Doctor</label><select class="field" name="doctorId">${doctors.map(x=>`<option value="${x._id}">${esc(x.name)}</option>`).join('')}</select></div></div><div id="rx-items"><div class="rx-item border border-line rounded-xl p-3 space-y-2"><label class="field-label">Medicine from clinic catalogue (optional)</label><select class="field rx-med"><option value="">Enter a medicine manually</option>${medOptions}</select><div class="grid sm:grid-cols-2 gap-2"><input class="field rx-name" placeholder="Medicine name *" required><input class="field rx-strength" placeholder="Strength"><input class="field rx-dose" placeholder="Dosage *" required><input class="field rx-route" placeholder="Route (oral, topical…)"><input class="field rx-frequency" placeholder="Frequency *" required><input class="field rx-duration" placeholder="Duration"><input class="field rx-quantity" type="number" min="0" placeholder="Quantity"><select class="field rx-food"><option value="">Food instruction</option><option value="before_food">Before food</option><option value="after_food">After food</option><option value="with_food">With food</option><option value="anytime">Anytime</option></select></div><textarea class="field h-16 py-2 rx-instructions" placeholder="Special instructions"></textarea></div></div><button type="button" id="add-rx-item" class="btn-secondary">+ Add another medicine</button><div><label class="field-label">Doctor notes</label><textarea class="field h-20 py-3" name="notes"></textarea></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="rx-form">Save prescription draft</button>');$('#rx-items').addEventListener('change',e=>{if(e.target.matches('.rx-med')){const o=e.target.selectedOptions[0],row=e.target.closest('.rx-item');if(o.value){row.querySelector('.rx-name').value=o.dataset.name;row.querySelector('.rx-strength').value=o.dataset.strength;row.dataset.medicineId=o.value}}});$('#add-rx-item').onclick=()=>{const first=$('.rx-item'),clone=first.cloneNode(true);clone.querySelectorAll('input,textarea').forEach(x=>x.value='');clone.querySelector('select').selectedIndex=0;delete clone.dataset.medicineId;$('#rx-items').append(clone)};$('#rx-form').onsubmit=async e=>{e.preventDefault();const items=[...document.querySelectorAll('.rx-item')].map(row=>({medicineId:row.dataset.medicineId||undefined,medicine:row.querySelector('.rx-name').value,strength:row.querySelector('.rx-strength').value,dosage:row.querySelector('.rx-dose').value,route:row.querySelector('.rx-route').value,frequency:row.querySelector('.rx-frequency').value,duration:row.querySelector('.rx-duration').value,quantity:row.querySelector('.rx-quantity').value,foodInstruction:row.querySelector('.rx-food').value,instructions:row.querySelector('.rx-instructions').value}));const f=new FormData(e.target);const body={patientId:f.get('patientId'),doctorId:f.get('doctorId'),items,notes:f.get('notes')};if(consultationId)body.consultationId=consultationId;try{await api('/prescriptions',{method:'POST',body:JSON.stringify(body)});closeModal();toast('Prescription draft saved');navigate('Prescriptions')}catch(x){toast(x.message,'error')}}}
async function downloadPrescriptionPdf(id){try{const r=await fetch(`${API}/prescriptions/${id}/pdf`,{headers:{Authorization:`Bearer ${state.token}`},credentials:'include'});if(!r.ok){const e=await r.json().catch(()=>({}));throw new Error(e.message||'PDF download failed')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`careflow-prescription-${id.slice(-8)}.pdf`;a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message,'error')}}
async function treatmentPlansPage(root){const d=(await api('/treatment-plans')).data||[];root.innerHTML=`${pageHeader('Treatment plans','Care instructions, procedures, lifestyle advice and follow-up.','<button id="new-plan" class="btn-primary">New treatment plan</button>')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Patient</th><th>Doctor</th><th>Instructions</th><th>Follow-up</th><th>Status</th></tr></thead><tbody>${d.map(x=>`<tr><td>${esc(x.patientId?.firstName)} ${esc(x.patientId?.lastName)}</td><td>${esc(x.doctorId?.name||'—')}</td><td>${esc((x.instructions||'').slice(0,100)||'—')}</td><td>${x.followUpAt?new Date(x.followUpAt).toLocaleDateString():'—'}</td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-state">No treatment plans recorded.</div></td></tr>'}</tbody></table></div></section>`;$('#new-plan').onclick=async()=>{const [p,doctors]=await Promise.all([api('/patients?limit=100'),api('/doctors?limit=100')]);const patients=p.data||[],ds=doctors.data||[];showModal('New treatment plan',`<form id="plan-form" class="field-grid"><div><label class="field-label">Patient</label><select class="field" name="patientId">${patients.map(x=>`<option value="${x._id}">${esc(x.firstName)} ${esc(x.lastName)} · ${esc(x.uhid)}</option>`).join('')}</select></div><div><label class="field-label">Doctor</label><select class="field" name="doctorId">${ds.map(x=>`<option value="${x._id}">${esc(x.name)}</option>`).join('')}</select></div><div class="full"><label class="field-label">Associated diagnoses</label><select class="field" name="diagnosisIds" id="plan-diagnoses" multiple size="3"></select></div><div class="full"><label class="field-label">Existing prescription references</label><select class="field" name="medicationReferences" id="plan-prescriptions" multiple size="3"></select></div><div class="full"><label class="field-label">Treatment instructions</label><textarea class="field h-24 py-3" name="instructions"></textarea></div><div><label class="field-label">Duration</label><input class="field" name="duration"></div><div><label class="field-label">Follow-up date</label><input class="field" name="followUpAt" type="date"></div><div class="full"><label class="field-label">Lifestyle / diet advice</label><textarea class="field h-20 py-3" name="lifestyleAdvice"></textarea></div><div class="full"><label class="field-label">Additional notes</label><textarea class="field h-20 py-3" name="notes"></textarea></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="plan-form">Save draft</button>');const loadPlanRefs=async()=>{const patientId=$('#plan-form').elements.patientId.value;try{const [dx,rx]=await Promise.all([api(`/patients/${patientId}/diagnoses`),api(`/prescriptions?patientId=${encodeURIComponent(patientId)}`)]);$('#plan-diagnoses').innerHTML=dx.data.map(x=>`<option value="${x._id}">${esc(x.code||'Custom')} · ${esc(x.description)}</option>`).join('');$('#plan-prescriptions').innerHTML=rx.data.filter(x=>['finalized','partially_dispensed','dispensed','amended'].includes(x.status)).map(x=>`<option value="${x._id}">${esc(x.prescriptionNo||x._id)} · ${(x.items||[]).map(i=>esc(i.medicine)).join(', ')}</option>`).join('')}catch(x){toast(x.message,'error')}};$('#plan-form').elements.patientId.onchange=loadPlanRefs;loadPlanRefs();$('#plan-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=Object.fromEntries(f);b.diagnosisIds=f.getAll('diagnosisIds');b.medicationReferences=f.getAll('medicationReferences');try{await api('/treatment-plans',{method:'POST',body:JSON.stringify(b)});closeModal();toast('Treatment plan saved');treatmentPlansPage(root)}catch(x){toast(x.message,'error')}}}}
async function clinicalTemplatesPage(root){const d=(await api('/clinical-templates?all=true')).data||[],canManage=state.user?.role==='hospital_admin';root.innerHTML=`${pageHeader('Clinical templates','Reusable specialty note structures. Templates never create diagnoses or prescriptions.',canManage?'<button id="new-template" class="btn-primary">Create template</button>':'')}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Type</th><th>Specialty</th><th>Sections</th><th>Status</th><th></th></tr></thead><tbody>${d.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td>${esc(x.specialty||'—')}</td><td>${x.sections?.length||0}</td><td>${x.active?'Active':'Inactive'}</td><td>${canManage?`<button class="btn-secondary" data-template-toggle="${x._id}" data-active="${x.active}">${x.active?'Deactivate':'Activate'}</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">No templates configured.</div></td></tr>'}</tbody></table></div></section>`;if(canManage)$('#new-template').onclick=()=>{showModal('Create clinical template',`<form id="template-form" class="field-grid"><div><label class="field-label">Template name</label><input class="field" name="name" required></div><div><label class="field-label">Type</label><select class="field" name="type">${['general','follow_up','cardiology','dermatology','orthopedics','gynecology','pediatrics','dental','physiotherapy','ent','ophthalmology','neurology','psychiatry','other'].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div><div class="full"><label class="field-label">Specialty</label><input class="field" name="specialty"></div><div class="full"><label class="field-label">Sections (one per line)</label><textarea class="field h-28 py-3" name="sections" placeholder="Chief complaint
History of present illness
Examination
Assessment
Plan" required></textarea></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="template-form">Save template</button>');$('#template-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),sections=String(f.get('sections')).split('\n').map((label,i)=>({key:label.toLowerCase().replace(/[^a-z0-9]+/g,'_'),label,order:i})).filter(x=>x.label);try{await api('/clinical-templates',{method:'POST',body:JSON.stringify({name:f.get('name'),type:f.get('type'),specialty:f.get('specialty'),sections})});closeModal();toast('Clinical template created');clinicalTemplatesPage(root)}catch(x){toast(x.message,'error')}}};root.querySelectorAll('[data-template-toggle]').forEach(b=>b.onclick=async()=>{try{await api(`/clinical-templates/${b.dataset.templateToggle}`,{method:'PATCH',body:JSON.stringify({active:b.dataset.active!=='true'})});toast('Template status updated');clinicalTemplatesPage(root)}catch(e){toast(e.message,'error')}})}

async function patientDiagnosticReports(root){const d=(await api('/patient-portal/diagnostic-reports')).data;root.innerHTML=`${pageHeader('My diagnostic reports','Only reports released by your healthcare provider are shown here.')}<section class="card mb-5"><div class="p-4 border-b border-line"><b>Laboratory reports</b></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Test</th><th>Order</th><th>Released</th><th>Results</th></tr></thead><tbody>${d.laboratory.map(r=>`<tr><td>${esc(r.testName||'Laboratory test')}</td><td>${esc(r.orderId?.orderNo||'—')}</td><td>${r.releasedAt?new Date(r.releasedAt).toLocaleString():'—'}</td><td><details><summary class="cursor-pointer text-mint">View results</summary><div class="text-xs mt-2">${(r.parameters||[]).map(p=>`<p>${esc(p.name)}: <b>${esc(p.value)}</b> ${esc(p.unit)} · ${esc(p.flag)} · Ref ${esc(p.referenceRange||'—')}</p>`).join('')}</div></details><button class="btn-secondary mt-2" data-lab-pdf="${r._id}">Download PDF</button></td></tr>`).join('')||'<tr><td colspan="4">No released laboratory reports.</td></tr>'}</tbody></table></div></section><section class="card"><div class="p-4 border-b border-line"><b>Radiology reports</b></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Study</th><th>Order</th><th>Released</th><th>Impression</th></tr></thead><tbody>${d.radiology.map(r=>`<tr><td>${esc(r.orderId?.serviceName||'Imaging')}</td><td>${esc(r.orderId?.orderNo||'—')}</td><td>${r.releasedAt?new Date(r.releasedAt).toLocaleString():'—'}</td><td>${esc(r.impression||'—')}<div><button class="btn-secondary mt-2" data-rad-pdf="${r._id}">Download PDF</button></div></td></tr>`).join('')||'<tr><td colspan="4">No released radiology reports.</td></tr>'}</tbody></table></div></section>`;root.querySelectorAll('[data-lab-pdf]').forEach(b=>b.onclick=()=>downloadDiagnosticPdf(`/patient-portal/diagnostic-reports/lab/${b.dataset.labPdf}/pdf`,'laboratory-report.pdf'));root.querySelectorAll('[data-rad-pdf]').forEach(b=>b.onclick=()=>downloadDiagnosticPdf(`/patient-portal/diagnostic-reports/radiology/${b.dataset.radPdf}/pdf`,'radiology-report.pdf'))}
async function downloadDiagnosticPdf(path,filename){try{const r=await fetch(`${API}${path}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.message||'Unable to download report')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message,'error')}}
function modulePage(root,name){const descriptions={'Medical Records':'Longitudinal clinical records and documents.','Prescriptions':'Prescription authoring and dispensing workflows.','Treatment Plans':'Care plans and follow-up milestones.','Specialty Templates':'Configurable specialty-specific clinical forms.','Wards & Beds':'Ward, room and bed directory and occupancy.','Nursing':'Nursing notes and medication administration records.','Radiology':'Imaging orders, reports and attachments.','Operation Theatre / ICU':'Procedure scheduling and critical-care operations.','Pharmacy Sales':'Dispensing and pharmacy sales.','Suppliers & Purchases':'Supplier directory and purchase orders.','Expiry Management':'Batch expiry and stock alerts.','Expenses':'Operational expense records.','Doctor Payouts':'Doctor settlement and payout records.','Financial Reports':'Collections, receivables and finance reporting.','Staff & HRM':'Employee directory and staff administration.','Attendance & Leave':'Shifts, attendance and leave approvals.','CRM & Feedback':'Patient feedback, complaints and follow-up tracking.','Notifications':'System and patient communication log.','Reports':'Operational reports and exports.','Revenue Analytics':'Revenue trends and collection analytics.','Patient Analytics':'Patient acquisition and visit analytics.','Doctor Performance':'Clinician workload and performance indicators.','Inventory Analytics':'Stock valuation and movement analysis.','Users & Roles':'User accounts and permission administration.','Branches & Departments':'Organization branch and department settings.','Settings':'Organization preferences and integrations.','Audit Logs':'Traceable user and data-access activity.'};root.innerHTML=`${pageHeader(name,descriptions[name]||'Healthcare operations workspace')}<section class="card p-8 sm:p-12 text-center max-w-3xl mx-auto"><div class="w-14 h-14 rounded-2xl bg-[#edf5f1] text-mint grid place-items-center mx-auto text-xl"><i class="fa-solid fa-screwdriver-wrench"></i></div><h2 class="font-bold text-lg mt-5">Module architecture reserved</h2><p class="text-xs text-muted max-w-lg mx-auto leading-6 mt-2">This module is included in the platform navigation and domain plan. Its production workflow is not yet implemented in this initial build; it is intentionally not represented as a working feature.</p><div class="inline-flex mt-5 rounded-full bg-[#fff5df] text-[#966716] px-3 py-1.5 text-[10px] font-semibold">Implementation pending</div></section>`}
function showModal(title,body,footer=''){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><section class="modal"><div class="modal-head"><h3 class="font-bold text-base">${title}</h3><button class="icon-btn" data-close><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()})}function closeModal(){$('#modal-root').innerHTML=''}

function authModal(type){if(type==='forgot'){showModal('Reset your password',`<form id="forgot-form" class="space-y-3"><div><label class="field-label">Account email</label><input class="field" name="email" type="email" required></div><div><label class="field-label">Workspace slug (if email is shared)</label><input class="field" name="tenantSlug"></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="forgot-form">Send reset instructions</button>');$('#forgot-form').onsubmit=async e=>{e.preventDefault();try{const r=await fetch(`${API}/auth/forgot-password`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const d=await r.json();if(!r.ok)throw new Error(d.message);closeModal();toast(d.message)}catch(x){toast(x.message,'error')}}}
if(type==='register'){showModal('Register your organization',`<form id="register-form" class="field-grid"><div class="full"><label class="field-label">Hospital / clinic name</label><input class="field" name="organization" required minlength="2"></div><div><label class="field-label">Administrator name</label><input class="field" name="name" required></div><div><label class="field-label">Work email</label><input class="field" name="email" type="email" required></div><div class="full"><label class="field-label">Password (minimum 12 characters)</label><input class="field" name="password" type="password" minlength="12" required></div></form>`,'<button class="btn-secondary" data-close>Cancel</button><button class="btn-primary" form="register-form">Create organization</button>');$('#register-form').onsubmit=async e=>{e.preventDefault();try{const r=await fetch(`${API}/auth/register-tenant`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const d=await r.json();if(!r.ok)throw new Error(d.message);closeModal();toast('Organization created. Workspace slug: '+d.data.slug)}catch(x){toast(x.message,'error')}}}}

function logout(){location.reload()} // login removed: nothing to sign out of
async function enterApp(){try{state.user=(await api('/auth/me')).data;try{state.moduleAccess=(await api('/phase11/modules/access')).data}catch{state.moduleAccess=null}$('#app-shell').classList.remove('hidden');$('#user-name').textContent=state.user.name;$('#user-role').textContent=state.user.role.replaceAll('_',' ');$('#user-avatar').textContent=state.user.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();renderNav();navigate('Dashboard')}catch(e){console.error('enterApp failed',e);$('#page-content').innerHTML='<div class="card p-6 text-sm text-red-600">Dashboard load nahi hua: '+esc(e.message||String(e))+'</div>';$('#app-shell').classList.remove('hidden')}}
$('#mobile-menu').onclick=()=>{$('#sidebar').classList.add('open');$('#mobile-overlay').classList.add('show')};$('#sidebar-close').onclick=()=>{$('#sidebar').classList.remove('open');$('#mobile-overlay').classList.remove('show')};$('#mobile-overlay').onclick=()=>{$('#sidebar').classList.remove('open');$('#mobile-overlay').classList.remove('show')};$('#quick-add').onclick=()=>showModal('Quick actions',`<div class="grid grid-cols-2 gap-3"><button class="btn-secondary justify-center py-4" data-quick="patient"><i class="fa-solid fa-user-plus"></i> Patient</button><button class="btn-secondary justify-center py-4" data-quick="appointment"><i class="fa-solid fa-calendar-plus"></i> Appointment</button><button class="btn-secondary justify-center py-4" data-quick="invoice"><i class="fa-solid fa-file-invoice"></i> Invoice</button><button class="btn-secondary justify-center py-4" data-quick="doctor"><i class="fa-solid fa-user-doctor"></i> Doctor</button></div>`);$('#modal-root').addEventListener('click',e=>{const b=e.target.closest('[data-quick]');if(!b)return;const v=b.dataset.quick;closeModal();if(v==='patient')patientModal();if(v==='appointment')appointmentModal();if(v==='invoice')invoiceModal();if(v==='doctor')navigate('Doctors')});$('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){state.patientQuery=e.target.value;navigate('Patients')}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape')closeModal()});
enterApp().finally(()=>{if(window.cfBootDone)window.cfBootDone()}); // tries saved token, refresh cookie, or DISABLE_AUTH dev mode; shows login only if all fail
const params=new URLSearchParams(location.search);if(params.has('reset')){showModal('Choose a new password',`<form id="reset-form"><label class="field-label">New password (minimum 12 characters)</label><input name="password" class="field" type="password" minlength="12" required></form>`,'<button class="btn-primary" form="reset-form">Update password</button>');$('#reset-form').onsubmit=async e=>{e.preventDefault();try{const r=await fetch(`${API}/auth/reset-password`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:params.get('reset'),password:new FormData(e.target).get('password')})});const d=await r.json();if(!r.ok)throw new Error(d.message);closeModal();toast('Password updated. Please sign in.');history.replaceState({},'',location.pathname)}catch(x){toast(x.message,'error')}}}
if(params.has('patientInvite')){showModal('Activate your patient portal',`<form id="patient-invite-accept" class="space-y-3"><p class="text-xs text-muted">Create a password to access your personal CareFlow portal.</p><label class="field-label">Your name</label><input class="field" name="name" minlength="2"><label class="field-label">Password (12+ characters)</label><input class="field" type="password" name="password" minlength="12" required></form>`,'<button class="btn-primary" form="patient-invite-accept">Activate account</button>');$('#patient-invite-accept').onsubmit=async e=>{e.preventDefault();try{const r=await fetch(`${API}/patient-portal/accept-invitation`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),token:params.get('patientInvite')})});const d=await r.json();if(!r.ok)throw new Error(d.message);closeModal();toast(d.message);history.replaceState({},'',location.pathname)}catch(x){toast(x.message,'error')}}}
if(params.has('doctorInvite')){showModal('Activate your doctor account',`<form id="doctor-invite-accept" class="space-y-3"><p class="text-xs text-muted">Set a secure password to activate your CareFlow doctor login.</p><label class="field-label">New password (12+ characters)</label><input class="field" type="password" name="password" minlength="12" required></form>`,'<button class="btn-primary" form="doctor-invite-accept">Activate account</button>');$('#doctor-invite-accept').onsubmit=async e=>{e.preventDefault();try{const r=await fetch(`${API}/doctors/accept-invitation`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),token:params.get('doctorInvite')})});const d=await r.json();if(!r.ok)throw new Error(d.message);closeModal();toast(d.message);history.replaceState({},'',location.pathname)}catch(x){toast(x.message,'error')}}}
if(params.has('verify')){fetch(`${API}/auth/verify-email`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:params.get('verify')})}).then(r=>r.json()).then(d=>{toast(d.message,d.success?'success':'error');history.replaceState({},'',location.pathname)}).catch(()=>toast('Email verification failed','error'))}
